const COLOR_PRESETS = ['#FAF7F0', '#FFFFFF', '#F5EFE6', '#FDF1F0', '#F3F5F0', '#EDEDED'];
// 색 고르기 칩 (섹션 배경색·안쪽 창 색): 기본 · 추천 색 동그라미 · 직접 고르기(무지개) - 지금 편집창 칩 스타일과 같게
const CPK_COLORS = ['#FAF7F0', '#FFFFFF', '#F5EFE6', '#FDF1F0', '#F3F5F0', '#EEF3F8', '#F2EEF7', '#EDEDED'];
const CPK_INK = ['#2B2B2B', '#5E5650', '#7A3B41', '#3F5BB0', '#2F7A4E', '#FFFFFF'];
function cpkHtml(id, val, isDef, resetId, list) {
    const L = list || CPK_COLORS, v = String(val || '').toUpperCase(), inL = L.some(c => c.toUpperCase() === v);
    const def = resetId ? `<button type="button" class="cpk-def${isDef ? ' on' : ''}" id="${resetId}" title="테마 기본 색"><i></i>기본</button>` : '';
    const cu = !isDef && !inL && v;
    return `<div class="cpk" data-cpk-for="${id}">${def}<label class="cpk-custom${cu ? ' on' : ''}" title="원하는 색 직접 고르기" style="--c:${cu ? v : 'transparent'}"><i></i><span>${cu ? v : '직접 고르기'}</span><input type="color" id="${id}" value="${esc(val || L[0])}"></label><span class="cpk-br"></span>${L.map(c => `<button type="button" class="cpk-sw${!isDef && c.toUpperCase() === v ? ' on' : ''}" data-cpk="${c}" style="--c:${c}" title="${c}"></button>`).join('')}</div>`;
}
function bindCpk(scope) {
    scope.querySelectorAll('.cpk').forEach(row => {
        const input = row.querySelector('input[type=color]');
        const mark = c => { row.querySelectorAll('.cpk-sw').forEach(b => b.classList.toggle('on', b.dataset.cpk.toUpperCase() === c.toUpperCase())); const cu = row.querySelector('.cpk-custom'); const inL = [...row.querySelectorAll('.cpk-sw')].some(b => b.dataset.cpk.toUpperCase() === c.toUpperCase()); cu.classList.toggle('on', !inL); cu.style.setProperty('--c', inL ? 'transparent' : c); cu.querySelector('span').textContent = inL ? '직접 고르기' : c.toUpperCase(); row.querySelector('.cpk-def')?.classList.remove('on'); };
        row.querySelectorAll('.cpk-sw').forEach(b => b.addEventListener('click', () => { input.value = b.dataset.cpk; mark(b.dataset.cpk); input.dispatchEvent(new Event('input', { bubbles: true })); input.dispatchEvent(new Event('change', { bubbles: true })); }));
        input.addEventListener('input', () => mark(input.value));
    });
}
function introBgOp(i) { const v = Number(i && i.bgOpacity); return i && i.bgOpacity != null && isFinite(v) ? Math.max(0, Math.min(100, v)) / 100 : 1; }
// 인트로 배경색 칸: 지금 디자인 색(바탕·포인트·글자·선)을 맨 앞에 + 기본 밝은 색들
function introBgSwatches() {
    const row = document.getElementById('is2Bg')?.nextElementSibling; if (!row || !row.classList.contains('color-preset-row')) return;
    const p = curPalOf(), cur = String(state.intro.bg || p.bg).toUpperCase(), seen = new Set();
    const list = [[p.bg, '디자인 바탕색'], [p.accent, '디자인 포인트 색'], [p.ink, '디자인 글자색'], [p.line, '디자인 선 색']].concat(COLOR_PRESETS.map(c => [c, c]))
        .filter(([c]) => c && /^#[0-9a-f]{6}$/i.test(c) && !seen.has(c.toUpperCase()) && seen.add(c.toUpperCase()));
    row.innerHTML = list.map(([c, t], i) => `<button type="button" class="color-preset-swatch${i < 4 && t !== c ? ' dsg' : ''}${c.toUpperCase() === cur ? ' on' : ''}" data-color="${c}" style="background:${c};" title="${t}"></button>`).join('');
    row.querySelectorAll('[data-color]').forEach(btn => btn.addEventListener('click', () => { const inp = document.getElementById('is2Bg'); inp.value = btn.dataset.color; inp.dispatchEvent(new Event('input', { bubbles: true })); introBgSwatches(); }));
}
function attachColorPresets(inputId) {
    const input = document.getElementById(inputId);
    if (!input || input.dataset.presetsAttached) return;
    input.dataset.presetsAttached = '1';
    const row = document.createElement('div');
    row.className = 'color-preset-row';
    row.innerHTML = COLOR_PRESETS.map(c => `<button type="button" class="color-preset-swatch" data-color="${c}" style="background:${c};" title="${c}"></button>`).join('');
    input.insertAdjacentElement('afterend', row);
    row.querySelectorAll('[data-color]').forEach(btn => btn.addEventListener('click', () => {
        input.value = btn.dataset.color;
        input.dispatchEvent(new Event('input', { bubbles: true }));
    }));
}

