function loadFontCss(fontId) {
    const f = fontOptions.find(x => x.id === fontId);
    if (!f || !f.cssUrl) return;
    if (document.querySelector(`link[data-font-id="${fontId}"]`)) return; // 이미 불러온 폰트면 중복 로드 안 함
    const link = document.createElement('link');
    link.rel = 'stylesheet'; link.href = f.cssUrl; link.dataset.fontId = fontId;
    document.head.appendChild(link);
}

// 오시는 길 지도(카카오맵) - developers.kakao.com 에서 발급받은 JavaScript 키를 넣어야 실제로 지도가 뜬다
const KAKAO_MAP_APP_KEY = '9d5208f041541d3a79f70ffc2f4f7c58';
let kakaoMapSdkLoading = null;
function loadKakaoMapSdk() {
    if (window.kakao && window.kakao.maps) return Promise.resolve();
    if (kakaoMapSdkLoading) return kakaoMapSdkLoading;
    kakaoMapSdkLoading = new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.src = `//dapi.kakao.com/v2/maps/sdk.js?appkey=${KAKAO_MAP_APP_KEY}&autoload=false&libraries=services`;
        script.onload = () => window.kakao.maps.load(resolve);
        script.onerror = reject;
        document.head.appendChild(script);
    });
    return kakaoMapSdkLoading;
}
function initLocationMaps(root) {
    (root || document).querySelectorAll('.location-map[data-address]').forEach(mapEl => {
        const address = mapEl.dataset.address;
        if (!address || mapEl.dataset.mapInited) return;
        mapEl.dataset.mapInited = '1';
        loadKakaoMapSdk().then(() => {
            const geocoder = new kakao.maps.services.Geocoder();
            geocoder.addressSearch(address, (result, status) => {
                if (status !== kakao.maps.services.Status.OK || !result[0]) {
                    console.warn('[카카오맵] 주소 검색 실패 - status:', status, '/ 주소:', address);
                    mapEl.innerHTML = `<p style="font-size:12px;color:#999;text-align:center;padding:20px 0;">지도를 표시할 수 없습니다 (주소를 확인해주세요)<br><span style="font-size:10px;">status: ${status}</span></p>`;
                    return;
                }
                // 지도/마커/컨트롤을 만드는 부분은 SDK 로딩과 별개의 단계인데, 지금까지 여기서 에러가 나도
                // 바깥의 SDK 로딩 실패 처리(.catch)로 잘못 흘러들어가서 "SDK를 못 불러왔다"는
                // 엉뚱한 메시지로 진짜 원인(예: 마커 생성 실패 등)이 가려지고 있었다. 따로 잡아서 진짜 원인을 보여준다.
                try {
                    const coords = new kakao.maps.LatLng(result[0].y, result[0].x);
                    const map = new kakao.maps.Map(mapEl, { center: coords, level: 3 });
                    new kakao.maps.Marker({ map, position: coords });
                    map.addControl(new kakao.maps.ZoomControl(), kakao.maps.ControlPosition.RIGHT); // 확대/축소 슬라이드 - 카카오맵 기본 제공 컨트롤
                    // 카카오맵은 생성 시점 컨테이너 크기를 기준으로 내부 캔버스를 그리고, 그 뒤로
                    // 컨테이너 폭이 바뀌어도(표준/좁게/꽉채움 등 화면모드 전환 시) 스스로 다시 맞추지
                    // 않는다 - relayout()을 직접 호출해줘야 한다. 안 해주면 지도가 처음 그렸던
                    // (다른) 크기 그대로 남아서 카드 폭보다 넓게 삐져나가 있었다(공개 페이지에서도
                    // 동일한 문제라 render-invite.js에도 같은 처리를 해뒀다).
                    if (typeof ResizeObserver !== 'undefined') {
                        let relayoutRaf = null;
                        new ResizeObserver(() => {
                            if (relayoutRaf) return;
                            relayoutRaf = requestAnimationFrame(() => {
                                relayoutRaf = null;
                                map.relayout();
                                map.setCenter(coords); // relayout()이 중심을 컨테이너 좌상단 기준으로 흐트러뜨리므로 다시 잡아준다
                            });
                        }).observe(mapEl);
                    }
                } catch (renderErr) {
                    console.error('[카카오맵] 지도 렌더링 중 오류:', renderErr);
                    mapEl.innerHTML = `<p style="font-size:12px;color:#999;text-align:center;padding:20px 0;">지도 렌더링 중 오류가 발생했습니다<br><span style="font-size:10px;">${esc(String(renderErr.message || renderErr))}</span></p>`;
                }
            });
        }).catch(err => {
            // 이 카탈로그(SDK 로드 자체 실패)의 가장 흔한 원인은 "이 도메인이 카카오 개발자센터에
            // JavaScript SDK 도메인으로 등록 안 돼있음" 이다 - 지금 보고 있는 실제 도메인을 같이 보여줘서 바로 확인 가능하게 한다.
            console.error('[카카오맵] SDK 로드 실패:', err, '/ 현재 도메인:', location.hostname);
            mapEl.innerHTML = `<p style="font-size:12px;color:#999;text-align:center;padding:20px 0;">지도를 불러오지 못했습니다<br><span style="font-size:10px;">현재 도메인(${location.hostname})이 카카오 개발자센터에 등록됐는지 확인해주세요</span></p>`;
        });
    });
}

// 오시는 길: 간격·지도 높이 한 값을 바꾸면 미리보기(손잡이·지도)·옆 −/＋ 숫자·편집창 슬라이더를 다 같이 맞춤 (다시 그리지 않음)
const LOC_LIM = { gapBtn: [0, 80, 2], mapHeight: [100, 500, 10] }; // [최소, 최대, −/＋ 한 번에] · gapBtn = 버튼 간격(안내전화↔지도, 지도↔길찾기 둘 다)
const LOC_INPUT = { gapBtn: 'locGapBtn', mapHeight: 'locMapHeight' };
function locSet(key, val) {
    const block = state.blocks.find(b => b.id === 'location'), L = LOC_LIM[key];
    if (!block || !L) return;
    val = Math.max(L[0], Math.min(L[1], Math.round(val)));
    if (key === 'gapBtn') { block.fields.gapCallMap = val; block.fields.gapMapLinks = val; } else block.fields[key] = val;
    const col = document.querySelector('#previewRoot .col[data-block-id="location"]');
    if (col) {
        if (key === 'mapHeight') col.querySelectorAll('.location-map').forEach(m => { m.style.height = val + 'px'; });
        else col.querySelectorAll('.loc-gap-handle').forEach(h => { h.style.height = val + 'px'; });
        col.querySelectorAll(`.loc-step[data-k="${key}"] em`).forEach(em => { em.textContent = (key === 'mapHeight' ? '지도 높이 ' : '버튼 간격 ') + val; });
    }
    const inp = document.getElementById(LOC_INPUT[key]); if (inp && +inp.value !== val) inp.value = val;
    const lab = document.getElementById(LOC_INPUT[key] + 'Val'); if (lab) lab.textContent = val + 'px';
    return val;
}
// 오시는 길 섹션 전용: 안내전화↔지도 간격, 지도↔버튼3개 간격, 지도 높이를 미리보기에서
// 직접 드래그로 조절 (사이드바 숫자 입력과 동일한 값을 공유하고, 서로 실시간으로 동기화됨).
function initLocationGapDragging(root) {
    const block = state.blocks.find(b => b.id === 'location');
    if (!block) return;
    (root || document).querySelectorAll('.loc-gap-handle').forEach(handle => {
        let dragging = false, startY = 0, startVal = 0;
        if (handle.dataset.locGap !== 'gapCallMap') return; // 지도↔길찾기 쪽은 지도 높이 손잡이와 겹쳐서 끌기 없음 (같은 값을 위쪽 막대로 조절)
        handle.addEventListener('pointerdown', e => {
            dragging = true;
            handle.classList.add('dragging');
            handle.setPointerCapture(e.pointerId);
            startY = e.clientY;
            startVal = block.fields.gapCallMap ?? 14;
            e.stopPropagation();
        });
        handle.addEventListener('pointermove', e => {
            if (!dragging) return;
            locSet('gapBtn', startVal + (e.clientY - startY));
        });
        handle.addEventListener('pointerup', () => {
            if (!dragging) return;
            dragging = false;
            handle.classList.remove('dragging');
            scheduleSnapshot();
        });
    });
    (root || document).querySelectorAll('.loc-map-resize-handle').forEach(handle => {
        let dragging = false, startY = 0, startVal = 0;
        handle.addEventListener('pointerdown', e => {
            dragging = true;
            handle.classList.add('dragging');
            handle.setPointerCapture(e.pointerId);
            startY = e.clientY;
            startVal = block.fields.mapHeight ?? 190;
            e.stopPropagation();
        });
        handle.addEventListener('pointermove', e => {
            if (!dragging) return;
            locSet('mapHeight', startVal + (e.clientY - startY));
        });
        handle.addEventListener('pointerup', () => {
            if (!dragging) return;
            dragging = false;
            handle.classList.remove('dragging');
            scheduleSnapshot();
        });
    });
    // 옆 −/＋: 누를 때마다 간격 2px · 지도 10px, 꾹 누르면 계속 (손잡이가 겹치거나 얇아도 정확히 조절)
    (root || document).querySelectorAll('.loc-step').forEach(st => {
        const key = st.dataset.k;
        let t = null, iv = null;
        const stop = () => { if (t || iv) scheduleSnapshot(); clearTimeout(t); clearInterval(iv); t = iv = null; };
        st.addEventListener('pointerdown', e => {
            e.stopPropagation(); // 손잡이 끌기·미리보기 고르기로 번지지 않게
            const b = e.target.closest('button[data-d]'); if (!b) return;
            e.preventDefault();
            const step = () => locSet(key, (key === 'mapHeight' ? (block.fields.mapHeight ?? 190) : (block.fields.gapCallMap ?? 14)) + (+b.dataset.d) * LOC_LIM[key][2]);
            step(); t = setTimeout(() => { iv = setInterval(step, 90); }, 380);
        });
        ['pointerup', 'pointerleave', 'pointercancel'].forEach(ev => st.addEventListener(ev, stop));
        st.addEventListener('click', e => e.stopPropagation());
    });
}

