// ↓ 버튼 "자유 위치": 미리보기에서 끌어서 자리 정하기 (사진+글자 칸 / 영상 화면 안 %) - 다른 끌기·범위선택보다 먼저 잡는다
(function initNextBtnDrag() {
    let d = null;
    window.addEventListener('pointerdown', e => {
        const btn = e.target.closest && e.target.closest('#previewRoot .ib-next-free');
        if (!btn || e.button > 0) return;
        const col = btn.closest('.col[data-block-id]'), ct = btn.closest('.blk-hero, .video-cover-wrap');
        const block = col && state.blocks.find(b => b.id === col.dataset.blockId);
        if (!block || !ct) return;
        e.preventDefault(); e.stopPropagation();
        const r = btn.getBoundingClientRect();
        d = { btn, ct, block, sx: e.clientX, sy: e.clientY, ox: e.clientX - (r.left + r.width / 2), oy: e.clientY - (r.top + r.height / 2), moved: false };
        try { btn.setPointerCapture(e.pointerId); } catch (err) {}
    }, true);
    window.addEventListener('pointermove', e => {
        if (!d) return;
        if (!d.moved && Math.hypot(e.clientX - d.sx, e.clientY - d.sy) < 4) return;
        d.moved = true; d.btn.classList.add('is-dragging');
        const c = d.ct.getBoundingClientRect();
        const x = Math.max(2, Math.min(98, ((e.clientX - d.ox - c.left) / c.width) * 100));
        const y = Math.max(2, Math.min(98, ((e.clientY - d.oy - c.top) / c.height) * 100));
        d.x = Math.round(x * 10) / 10; d.y = Math.round(y * 10) / 10;
        d.btn.style.left = d.x + '%'; d.btn.style.top = d.y + '%';
    }, true);
    const end = () => {
        if (!d) return;
        const cur = d; d = null;
        cur.btn.classList.remove('is-dragging');
        if (!cur.moved) return; // 제자리에서 뗐으면 그냥 클릭 = 다음 섹션으로
        cur.btn._dragged = true; setTimeout(() => { cur.btn._dragged = false; }, 400);
        cur.block.fields.nextX = cur.x; cur.block.fields.nextY = cur.y;
        scheduleSnapshot();
    };
    window.addEventListener('pointerup', end, true);
    window.addEventListener('pointercancel', end, true);
})();
