let multiSelectMode = false;

// ===== 되돌리기(Ctrl+Z) / 다시하기 =====
// renderPreview()가 사실상 "상태가 바뀔 때마다" 호출되는 지점이라 거기 한 군데에만 걸어서,
// 코드 곳곳의 개별 수정 지점을 일일이 손보지 않고도 전체 변경을 추적한다.
let undoStack = [];
let redoStack = [];
// 되돌리기 기록은 내용만 (간편 만들기에서 지금 보는 화면 spView·spAt은 빼고 - 예전엔 목록 화면에서 되돌리기를 누르면 질문 화면으로 튀었음)
const HIST_UI_KEYS = ['spView', 'spAt', 'spPvSeen'];
const histJSON = () => JSON.stringify(state, function (k, v) { return this === state && HIST_UI_KEYS.includes(k) ? undefined : v; });
const histParse = j => { const ui = {}; HIST_UI_KEYS.forEach(k => { if (state && state[k] !== undefined) ui[k] = state[k]; }); return Object.assign(JSON.parse(j), ui); };
let lastSnapshotJSON = histJSON();
let isRestoringHistory = false;

// 한 번의 끌기·돌리기·크기 조절(누르고 → 움직이고 → 뗄 때까지)은 되돌리기 기록 하나로 (예전엔 회전 손잡이가 각도마다 기록을 남겼음)
//  미리보기(청첩장·인트로) 안이나 선택 손잡이를 누르면 기록을 잠깐 모았다가, 손을 떼면 한 번만 남김
let histHold = false, histPend = false;
function histEnd() { if (!histHold) return; histHold = false; if (histPend) { histPend = false; scheduleSnapshot(); } }
document.addEventListener('pointerdown', e => {
    histEnd();
    const t = e.target;
    if (t && t.closest && t.closest('#phoneFrame, #introPreviewCanvas, .sticker-gizmo, .sf-handle, [data-handle]')) histHold = true;
}, true);
['pointerup', 'pointercancel'].forEach(ev => window.addEventListener(ev, () => setTimeout(histEnd, 0))); // (손잡이 쪽 pointerup 처리가 다 끝난 뒤)
window.addEventListener('blur', histEnd);
function scheduleSnapshot() {
    if (isRestoringHistory) return;
    if (histHold) { histPend = true; return; }
    const current = histJSON();
    if (current === lastSnapshotJSON) return;
    undoStack.push(lastSnapshotJSON);
    if (undoStack.length > 80) undoStack.shift(); // 너무 오래된 기록은 버려서 메모리 아낌
    lastSnapshotJSON = current;
    redoStack = []; // 새 변경이 생기면 이전에 되돌렸던 redo 기록은 의미가 없어짐
    updateHistoryButtons();
    try { spAutoSaveSoon(); } catch (e) {} // 간편 만들기: 몇 초 뒤 저절로 저장
    console.log('[history] 변경 감지, undoStack 길이:', undoStack.length);
}

function undoHistory() {
    if (!undoStack.length) return;
    redoStack.push(lastSnapshotJSON);
    const prev = undoStack.pop();
    isRestoringHistory = true;
    try {
        state = histParse(prev);
        lastSnapshotJSON = prev;
        renderSkinPicker(); renderFontBgPickers(); renderBlockList(); renderFieldEditor(); renderPreview();
        spAfterHistory();
    } finally {
        // 복원 도중 어디서 에러가 나더라도 이 플래그는 반드시 풀어야 한다 - 안 그러면
        // scheduleSnapshot()이 계속 무시되면서 그 뒤로 아무 변경도 기록 안 되는 것처럼 보임
        isRestoringHistory = false;
        updateHistoryButtons();
    }
}

function redoHistory() {
    if (!redoStack.length) return;
    undoStack.push(lastSnapshotJSON);
    const next = redoStack.pop();
    isRestoringHistory = true;
    try {
        state = histParse(next);
        lastSnapshotJSON = next;
        renderSkinPicker(); renderFontBgPickers(); renderBlockList(); renderFieldEditor(); renderPreview();
        spAfterHistory();
    } finally {
        isRestoringHistory = false;
        updateHistoryButtons();
    }
}

// 간편 만들기 화면에서 되돌리기·다시하기를 하면 지금 단계 칸도 되돌린 값으로 다시 그림 (보던 자리 그대로)
function spAfterHistory() {
    if (!document.documentElement.classList.contains('simple-mode')) return;
    try { spAccCache = {}; spRender(); } catch (e) {}
}
function updateHistoryButtons() {
    document.querySelectorAll('#spUndo').forEach(u => { u.disabled = undoStack.length === 0; });
    document.querySelectorAll('#spRedo').forEach(r => { r.disabled = redoStack.length === 0; });
    document.getElementById('historyUndo').disabled = undoStack.length === 0;
    document.getElementById('historyRedo').disabled = redoStack.length === 0;
    document.querySelectorAll('#udUndo, .mm-undo').forEach(u => { u.disabled = undoStack.length === 0; });
    document.querySelectorAll('#udRedo, .mm-redo').forEach(r => { r.disabled = redoStack.length === 0; });
}
// 문제 생기면 콘솔에서 __historyDebug() 실행해서 바로 상태 확인 가능
window.__historyDebug = () => console.log({
    undoStackLength: undoStack.length,
    redoStackLength: redoStack.length,
    isRestoringHistory,
    lastSnapshotMatchesCurrent: lastSnapshotJSON === histJSON(),
});
let selectedParts = new Set(); // "blockId::partKey" 형태로 저장
let gridSnapEnabled = true;
let touchDragMode = true; // 터치로도 바로 드래그 가능(끄면 스크롤이 우선되고, 탭으로만 선택/편집)
const GRID_STEP = 2; // % 단위 - 촘촘한 그리드(50칸)
function snapToGrid(v) { return gridSnapEnabled ? Math.round(v / GRID_STEP) * GRID_STEP : v; }

