// 장식 효과 진하기(투명도) - state.effects.ambientOpacity (10~100, 기본 100)
function syncAmbientOpacityUI() {
    const v = state.effects?.ambientOpacity ?? 100;
    const r = document.getElementById('ambientOpacity'); if (r) r.value = v;
    const l = document.getElementById('ambientOpacityVal'); if (l) l.textContent = v + '%';
    const g = document.getElementById('ambientOpacityGroup'); if (g) g.classList.toggle('st-off', (state.effects?.ambient || 'none') === 'none'); // 효과가 없으면 진하기 칸은 흐리게
    const kind = state.effects?.ambient || 'none', A = (window.InviteBlocks && InviteBlocks.AMBIENT) || {};
    const opts = document.getElementById('ambientOpts');
    if (opts) {
        opts.hidden = kind === 'none';
        const noDir = ['flash', 'sunset', 'rain', 'fireworks', 'popper', 'meteor'].includes(kind); // 정해진 움직임만 있는 효과 (날씨 따라는 고른 효과에 적용)
        const dirRow = document.getElementById('ambientDirRow'); if (dirRow) dirRow.hidden = noDir;
        const dn = document.getElementById('ambientDirNone'); if (dn) dn.hidden = !noDir;
        const wi = document.getElementById('ambientWeatherInfo'); if (wi) { wi.hidden = kind !== 'weather'; if (kind === 'weather' && !wi.textContent) wi.textContent = '예식장 지역의 지금 날씨에 맞춰 효과가 바뀌어요 (맑음 → 선샤인 · 밤 → 별똥별 · 흐림·안개 → 빛망울 · 비 → 빗방울 · 눈 → 눈꽃). 30분마다 새로 확인해요.'; }
        const defUp = A[kind] && A[kind].mode === 'rise';
        const curDir = state.effects?.ambientDir || (defUp ? 'up' : 'down'); // 고른 적 없으면 효과 기본 방향에 표시
        document.querySelectorAll('#ambientMoveOpts [data-amb-dir]').forEach(b => b.classList.toggle('on', b.dataset.ambDir === curDir));
        const mc = document.getElementById('ambientMoveCur'); if (mc) mc.textContent = (noDir ? '' : ({ still: '화면 고정', up: '위로', down: '아래로' }[curDir] + ' · ')) + (state.effects?.ambientOpacity ?? 100) + '%';
    }
    const ho = document.getElementById('ambientHeroOnly'); if (ho) ho.checked = state.effects?.ambientScope === 'hero';
    const hg = document.getElementById('ambientHeroGroup'); if (hg) hg.classList.toggle('st-off', kind === 'none');
}
