let musicTracksCache = null;
async function loadMusicTracks() {
    if (musicTracksCache) return musicTracksCache;
    try { const r = await fetch('music_list.php', { cache: 'no-cache' }); const d = await r.json(); musicTracksCache = d.ok ? d.tracks : []; }
    catch (e) { musicTracksCache = []; }
    return musicTracksCache;
}
