    if (!defs.length && !block.fields.layout) { wrap.innerHTML = `<h3>${blockLabels[block.id]} 편집</h3><p class="field-hint">실제 버전에서는 사진 업로드·개수 편집이 들어갑니다. 지금은 폭에 맞춰 장수만 자동 조절됩니다.</p>`; return; }
    const hasFreeLayout = !!block.fields.layout;
