    const box = document.createElement('div');
    box.className = 'field nbp';
    box.dataset.pzKind = 'inline-end';
    if (!InviteBlocks.heroTextOn(f, kind)) return; // 글자가 아래 칸에 있으면 ↓ 칸 자체를 안 보여줌 (안내 문구도 없이 - 편집창이 길어지지 않게)
