// ===== 히어로 사진 "높이조정"(가로 100% + heroRatio px): 미리보기 사진 아래 끝의 ↕ 손잡이를 위아래로 끌어서 높이 정하기 =====
//  섹션 편집창을 닫아도 미리보기에서 바로 조정 (끄는 동안 사진에 노란 점선) - 손을 떼면 편집창 슬라이더 값도 같이 맞춰짐
// ===== 히어로 "사진 아래 글자 칸" 높이: 미리보기 사진 바로 아래 노란 칸을 끌어서 (편집창 슬라이더 대신) =====
// 휴대폰: 미리보기에서 높이를 정하고 OK를 누르면 섹션 창을 다시 열어 그 섹션 옵션으로 돌아감
function reopenSectionPanel(id) {
    if (!hhMobile() || document.querySelector('.sections-sheet.popup-open, .field-drawer.popup-open')) return;
    selectedId = id; accOpen = true;
    renderBlockList(); renderFieldEditor(); updateSectionRuler();
    openSectionsSheet();
    setTimeout(() => { const t = [...document.querySelectorAll('#fieldEditor .pz-tl')].find(x => /높이|글자 자리/.test(x.textContent)); t && t.scrollIntoView({ block: 'center', behavior: 'smooth' }); }, 350);
}
