        const block = state.blocks.find(b => b.id === id), f = block.fields;
        const hero = root.querySelector(id === 'hero' ? '.col[data-block-id="hero"] .blk-hero.hero-text-over' : '.col[data-block-id="heroVideo"] .blk-hero-video');
        const pw = hero && hero.querySelector(id === 'hero' ? ':scope > .hero-photo-wrap' : ':scope > .video-cover-wrap'), sp = hero && hero.querySelector(':scope > .hero-text-space');
        if (!pw || !sp || hero.querySelector('.hb-area')) return;
        const what = id === 'hero' ? '사진' : '영상';
        const val = () => id === 'hero' ? Math.max(0, Math.min(500, Number(f.heroTextSpace) || 0)) : InviteBlocks.videoBandSpace(f);
        const area = document.createElement('div'); area.className = 'hb-area';
        const h = document.createElement('button'); h.type = 'button'; h.className = 'hb-handle'; h.title = `위아래로 끌어서 ${what} 아래 글자 칸 높이 정하기`;
        h.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M12 4v16M8 7.5L12 4l4 3.5M8 16.5l4 3.5 4-3.5"/></svg><b></b>';
        const ok = document.createElement('button'); ok.type = 'button'; ok.className = 'hh-ok hb-ok'; ok.textContent = 'OK'; ok.title = '다 정했어요 (노란 칸 숨기기)';
