function msPanelSync() {
    const n = multiSelectMode ? selectedParts.size : 0;
    if (!n) { msBox?.remove(); msBox = null; return; }
    if (!msBox) {
        msBox = document.createElement('div');
        msBox.className = 'text-toolbar intro-tt ms-tt';
        document.body.appendChild(msBox);
        msBox.addEventListener('pointerdown', e => e.stopPropagation());
    }
    const items = msItems(), txt = items.filter(x => !x.img);
    const col = msCommon(L => (L.color || '').toUpperCase()), font = msCommon(L => L.font), al = msCommon(L => L.align || 'center');
    const ic = d => `<svg viewBox="0 0 16 16" aria-hidden="true"><path d="${d}" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>`;
    msBox.innerHTML = `
        <div class="itt-head"><b class="itt-title"><i>✓</i>${n}개 골랐어요</b><button type="button" class="tt-close" title="고르기 풀기 (Esc)">✕</button></div>
        <div class="itt-row"><small>위치</small><div class="ms-pos">
            <button type="button" data-ms-pos="left" title="왼쪽 끝 맞추기">${ic('M2.5 2v12M5 5h8M5 11h5')}</button>
            <button type="button" data-ms-pos="center" title="모두 가로 가운데로">${ic('M8 2v12M3.5 5h9M5 11h6')}</button>
            <button type="button" data-ms-pos="right" title="오른쪽 끝 맞추기">${ic('M13.5 2v12M3 5h8M6 11h5')}</button></div></div>
        ${txt.length ? `
        <div class="itt-row"><small>정렬</small>${ittAlignHtml()}</div>
        <div class="itt-row"><small>크기</small><div class="ms-step"><button type="button" data-act="ms-fs-dec" title="작게">−</button><button type="button" data-act="ms-fs-inc" title="크게">＋</button></div></div>
        <div class="itt-row"><small>자간</small><div class="ms-step"><button type="button" data-act="ms-ls-dec" title="좁게">−</button><button type="button" data-act="ms-ls-inc" title="넓게">＋</button></div></div>
        <div class="itt-row"><small>글꼴</small>${ittFontHtml(font == null ? '__mix' : font)}</div>
        <div class="itt-row"><small>색</small>${ittColorHtml(col || '')}</div>
        <div class="itt-row"><small>테두리</small>${ittEdgeHtml(txt.length ? txt[0].L : {})}</div>` : ''}
        <div class="ms-foot">끌면 같이 옮겨져요 · 방향키로 미세 이동 · Esc 해제</div>`;
    if (font == null) { const sel = msBox.querySelector('select[data-act="font"]'); if (sel) { sel.insertAdjacentHTML('afterbegin', '<option value="__mix" selected disabled>여러 글꼴</option>'); } }
    msBox.querySelectorAll('[data-align]').forEach(b => b.classList.toggle('active', al === b.dataset.align));
    msBox.querySelector('.tt-close').addEventListener('click', () => { if (typeof exitAutoMulti === 'function' && multiAuto) exitAutoMulti(); else clearMultiSelect(); });
    // 위치 맞추기: 글자 상자의 실제 왼쪽·오른쪽 끝(섹션 폭 기준 %)을 가장 바깥 것에 맞춤 / 가운데는 x=50
    msBox.querySelectorAll('[data-ms-pos]').forEach(b => b.addEventListener('click', () => {
        const how = b.dataset.msPos, its = msItems();
        const geo = its.map(x => { const c = x.el.closest('.drag-canvas'), cr = c.getBoundingClientRect(), r = x.el.getBoundingClientRect();
            return { x, l: (r.left - cr.left) / cr.width * 100, rr: (r.right - cr.left) / cr.width * 100, w: r.width / cr.width * 100 }; });
        const minL = Math.min(...geo.map(g => g.l)), maxR = Math.max(...geo.map(g => g.rr));
        geo.forEach(g => {
            const nx = how === 'center' ? 50 : how === 'left' ? minL + g.w / 2 : maxR - g.w / 2;
            g.x.L.x = Math.round(Math.min(98, Math.max(2, nx)) * 100) / 100; g.x.el.style.left = g.x.L.x + '%';
        });
        scheduleSnapshot();
    }));
    msBox.querySelectorAll('[data-align]').forEach(b => b.addEventListener('click', () => {
        msApply(x => { if (!x.img) { x.L.align = b.dataset.align; x.el.style.textAlign = b.dataset.align; } });
        msBox.querySelectorAll('[data-align]').forEach(o => o.classList.toggle('active', o === b));
    }));
    const step = (k, d) => msApply(x => { if (x.img) return;
        if (k === 'fs') { x.L.fontSize = Math.min(72, Math.max(6, Math.round((x.L.fontSize + d) * 10) / 10)); x.el.style.fontSize = fontToCqw(x.L.fontSize); }
        else { const v = Math.max(-100, Math.min(400, Math.round((x.L.ls || 0) + d))); if (v) x.L.ls = v; else delete x.L.ls; x.el.style.letterSpacing = lsEm(v); } });
    msBox.querySelector('[data-act="ms-fs-dec"]')?.addEventListener('click', () => step('fs', -0.5));
    msBox.querySelector('[data-act="ms-fs-inc"]')?.addEventListener('click', () => step('fs', 0.5));
    msBox.querySelector('[data-act="ms-ls-dec"]')?.addEventListener('click', () => step('ls', -10));
    msBox.querySelector('[data-act="ms-ls-inc"]')?.addEventListener('click', () => step('ls', 10));
    msBox.querySelector('select[data-act="font"]')?.addEventListener('change', e => {
        const id = e.target.value; if (id) loadFontCss(id);
        msApply(x => { if (x.img) return; if (id) x.L.font = id; else delete x.L.font; x.el.style.fontFamily = partFontFamily(id); });
    });
    bindIttColor(msBox, () => msCommon(L => (L.color || '').toUpperCase()) || '', c => msApply(x => { if (x.img) return; if (c) x.L.color = c; else delete x.L.color; x.el.style.color = c || ''; }));
    bindIttEdge(msBox, q => q === 'color' ? (txt[0] && txt[0].L.glow) : edgeOf(txt[0] && txt[0].L), (m, c) => msApply(x => { if (x.img) return; setEdge(x.L, m, c); x.el.style.textShadow = textEdge(x.L); }));
    msPlace();
}
window.addEventListener('resize', () => msPlace());

// 미리보기 위에서 더블클릭하면 그 자리에서 바로 타이핑할 수 있게 함
function startInlineEdit(el, block, part) {
    if ((block.fields.heroLayers || []).includes(part)) el.innerText = block.fields[part] || ''; // 메인 문구 칸: {신랑} 같은 원래 글로 고침
    el.setAttribute('contenteditable', 'true');
    el.style.cursor = 'text';
    el.focus();
    document.execCommand('selectAll', false, null);

    const onKeydown = e => {
        e.stopPropagation();
        if (e.key === 'Enter') { e.preventDefault(); document.execCommand('insertLineBreak'); }
        if (e.key === 'Escape') { e.preventDefault(); el.blur(); }
    };
    const commit = () => {
        el.removeAttribute('contenteditable');
        el.style.cursor = '';
        el.removeEventListener('blur', commit);
        el.removeEventListener('keydown', onKeydown);
        block.fields[part] = el.innerText.replace(/\n+$/, '');
        if ((block.id === 'hero' || block.id === 'heroVideo') && (part === 'groomName' || part === 'brideName')) {
            weddingInfo()[part === 'groomName' ? 'groom' : 'bride'] = block.fields[part];
            applyWeddingInfo('names'); refreshWeddingInfoCard();
        }
        renderPreview();
        if (selectedId === block.id) renderFieldEditor();
    };
    el.addEventListener('blur', commit);
    el.addEventListener('keydown', onKeydown);
}

// 팝업의 수치(글자 크기/눌러펴기/줄바꿈 폭)를 더블클릭하면 직접 입력할 수 있게 함
function bindEditableValue(box, key, min, max, setVal, getVal, applyFn) {
    const span = box.querySelector(`[data-val="${key}"]`);
    if (!span) return;
    span.title = '더블클릭해서 직접 입력';
    span.addEventListener('dblclick', e => {
        e.stopPropagation();
        const current = getVal();
        const input = document.createElement('input');
        input.type = 'number';
        input.step = 'any';
        input.value = current;
        input.className = 'tt-val-input';
        span.replaceWith(input);
        input.focus();
        input.select();

        const commit = () => {
            let v = parseFloat(input.value);
            if (isNaN(v) || !isFinite(v)) v = current;
            v = Math.round(Math.min(max, Math.max(min, v)) * 10) / 10;
            setVal(v);
            const freshSpan = document.createElement('span');
            freshSpan.className = 'tt-val';
            freshSpan.setAttribute('data-val', key);
            input.replaceWith(freshSpan);
            bindEditableValue(box, key, min, max, setVal, getVal, applyFn);
            applyFn();
        };
        input.addEventListener('blur', commit);
        input.addEventListener('keydown', e2 => {
            e2.stopPropagation();
            if (e2.key === 'Enter') { e2.preventDefault(); input.blur(); }
            if (e2.key === 'Escape') { e2.preventDefault(); input.value = current; input.blur(); }
        });
    });
}

// 드래그 중일 때만 그리드 라인을 보여줌(그리드 스냅이 켜져 있을 때만)
function showGridLines(canvases) {
    if (!gridSnapEnabled) return;
    canvases.forEach(c => c && c.classList.add('grid-snap-lines'));
}
function hideGridLines() {
    document.querySelectorAll('.grid-snap-lines').forEach(c => c.classList.remove('grid-snap-lines'));
}

function deselectPart() {
    if (window._activeSelection) {
        window._activeSelection.frame.remove();
        window._activeSelection.box.remove();
        window._activeSelection = null;
    }
    if (window._ttOutsideHandler) { document.removeEventListener('pointerdown', window._ttOutsideHandler, true); window._ttOutsideHandler = null; }
}

// 선택 박스 위/아래 손잡이: 위 = 글자 크기, 아래 = 회전. 에디터 문구와 인트로 문구가 같이 쓴다.
// o = { canvas, el, getFs, setFs, minFs, maxFs, getRot, setRot, apply }
function addSizeRotateHandles(frame, o) {
    frame.insertAdjacentHTML('beforeend',
        '<div class="sf-stem sf-stem-top"></div><div class="sf-stem sf-stem-bottom"></div>' +
        '<div class="sf-handle sf-size" title="글자 크기 (위로 끌면 커지고 아래로 끌면 작아져요)">A</div>' +
        '<div class="sf-handle sf-rot" title="회전 (돌려서 조절)">↻</div>');
    const sizeH = frame.querySelector('.sf-size'), rotH = frame.querySelector('.sf-rot');

    let sizing = false, sy = 0, startFs = 0;
    sizeH.addEventListener('pointerdown', e => {
        e.stopPropagation(); e.preventDefault();
        sizing = true; sizeH.setPointerCapture(e.pointerId);
        sy = e.clientY; startFs = o.getFs();
    });
    sizeH.addEventListener('pointermove', e => {
        if (!sizing) return;
        const cw = o.canvas.getBoundingClientRect().width || 1;
        // 캔버스 폭 대비 이동량으로 환산 (기준폭 390px 글자크기 단위) - 화면 크기/축소 여부와 무관하게 같은 감각
        const d = (-(e.clientY - sy) / cw * 390) * 0.5;
        o.setFs(Math.min(o.maxFs, Math.max(o.minFs, Math.round((startFs + d) * 2) / 2)));
        o.apply();
    });
    sizeH.addEventListener('pointerup', () => { sizing = false; });

    let rotating = false, cx = 0, cy = 0, startAngle = 0, startRot = 0;
    const angleAt = e => Math.atan2(e.clientY - cy, e.clientX - cx) * 180 / Math.PI;
    rotH.addEventListener('pointerdown', e => {
        e.stopPropagation(); e.preventDefault();
        rotating = true; rotH.setPointerCapture(e.pointerId);
        const r = o.el.getBoundingClientRect(); // 회전해도 중심점은 그대로
        cx = r.left + r.width / 2; cy = r.top + r.height / 2;
        startAngle = angleAt(e); startRot = o.getRot();
    });
    rotH.addEventListener('pointermove', e => {
        if (!rotating) return;
        let rot = startRot + (angleAt(e) - startAngle);
        rot = ((rot + 180) % 360 + 360) % 360 - 180;
        if (Math.abs(rot) < 3) rot = 0; // 0도 근처에서는 자석처럼 딱 맞춰준다
        o.setRot(Math.round(rot));
        o.apply();
    });
    rotH.addEventListener('pointerup', () => { rotating = false; });
}

// 파츠를 클릭하면 (1) 포토샵 자유 변형처럼 모서리/변 드래그 핸들이 달린 선택 박스와
// (2) 세부 수치를 조절하는 팝업을 함께 띄운다. 둘 다 같은 layout 객체를 공유해서 실시간으로 같이 움직인다.
function selectPart(el, block, part) {
    deselectPart();
    const canvas = el.closest('.drag-canvas');
    if (!canvas) return;
    const layout = partLayout(block, part, el, true);
    if (!layout) return;

    const frame = document.createElement('div');
    frame.className = 'selection-frame';
    frame.innerHTML = `
        <div class="sf-handle sf-nw" data-handle="nw"></div>
        <div class="sf-handle sf-ne" data-handle="ne"></div>
        <div class="sf-handle sf-w" data-handle="w"></div>
        <div class="sf-handle sf-e" data-handle="e"></div>
        <div class="sf-handle sf-sw" data-handle="sw"></div>
        <div class="sf-handle sf-se" data-handle="se"></div>
    `;
    canvas.appendChild(frame);

    const syncFrame = () => {
        const cRect = canvas.getBoundingClientRect();
        const eRect = el.getBoundingClientRect();
        // 좁은화면 모드는 .invite-preview 전체를 transform:scale()로 줄여서 보여준다. getBoundingClientRect()는
        // 이미 줄어든 "화면상 px"인데 frame은 그 줄어든 캔버스 "안"에 붙어 있어서, 그대로 넣으면 한 번 더 줄어
        // 박스가 쪼그라들고 핸들이 뭉쳐 보였다 - 캔버스의 현재 축소 비율로 나눠서 원래 좌표계로 되돌린다.
        const k = (canvas.offsetWidth && cRect.width) ? cRect.width / canvas.offsetWidth : 1;
        frame.style.left = ((eRect.left - cRect.left) / k) + 'px';
        frame.style.top = ((eRect.top - cRect.top) / k) + 'px';
        frame.style.width = (eRect.width / k) + 'px';
        frame.style.height = (eRect.height / k) + 'px';
        // 핸들도 같이 줄어들어 누르기 어려워지므로 축소 비율만큼 키워서 화면상 크기를 유지한다
        frame.style.setProperty('--sf-k', 1 / k);
    };
    syncFrame();

    const box = document.createElement('div');
    box.className = 'text-toolbar intro-tt';
    const isImagePart = IMAGE_PARTS.has(part);
    box.innerHTML = `
        <div class="itt-head"><b class="itt-title"><i>${isImagePart ? '▣' : 'Aa'}</i>${esc(partLabels[part] || (/^hl_/.test(part) ? '문구 · ' + String(InviteBlocks.heroFill(block.fields[part] || '', block.fields) || '').replace(/\s+/g, ' ').slice(0, 14) : part))}</b>${part === 'heart' && (block.id === 'hero' || block.id === 'heroVideo') ? '<button type="button" class="itt-del" data-act="heart-del" title="하트 지우기 (편집창에서 다시 넣을 수 있어요)">🗑 지우기</button>' : ''}<button type="button" class="tt-close" aria-label="닫기">✕</button></div>
        ${isImagePart ? `
        <div class="itt-row"><small>크기</small><div class="itt-step"><button type="button" data-act="w-dec">−</button><span class="tt-val" data-val="w">${layout.widthAuto ? '자동' : Math.round(layout.width) + '%'}</span><button type="button" data-act="w-inc">+</button></div></div>` : `
        <div class="itt-grid">
            ${ittCell('크기', 'fs', layout.fontSize + 'px')}${ittCell('회전', 'rot', (layout.rotation || 0) + '°')}
            ${ittCell('장평', 'sx', layout.scaleX + '%')}${ittCell('자간', 'ls', ittLsText(layout.ls))}
        </div>
        <div class="itt-row"><small>줄 폭</small>${ittAutoWHtml(layout.widthAuto || layout.widthFit)}</div>
        <div class="itt-row"><small>정렬</small>${ittAlignHtml()}</div>
        <div class="itt-row"><small>글꼴</small>${ittFontHtml(layout.font)}</div>
        <div class="itt-row"><small>색</small>${ittColorHtml(layout.color)}</div>
        <div class="itt-row"><small>테두리</small>${ittEdgeHtml(layout)}</div>
        <div class="itt-row tt-pos"><small>위치</small><div class="itt-nudge"><button type="button" data-nudge="left" title="왼쪽">←</button><button type="button" data-nudge="up" title="위">↑</button><button type="button" class="mid" data-act="center-x" title="좌우 가운데로">가운데</button><button type="button" data-nudge="down" title="아래">↓</button><button type="button" data-nudge="right" title="오른쪽">→</button></div></div>`}
    `;
    document.body.appendChild(box);

    const positionToolbar = () => {
        const rect = el.getBoundingClientRect();
        const bw = box.offsetWidth, bh = box.offsetHeight;
        let left = rect.left + rect.width / 2 - bw / 2;
        let top = rect.top - bh - 46; // 위쪽 크기 손잡이가 팝업에 가려지지 않게 여유를 둔다
        if (top < 8) top = rect.bottom + 46; // 아래쪽 회전 손잡이도 마찬가지
        left = Math.min(window.innerWidth - bw - 8, Math.max(8, left));
        box.style.left = left + 'px'; box.style.top = top + 'px'; fitTT(box);
    };
    positionToolbar();

    const apply = () => {
        if (!isImagePart) {
            el.style.fontSize = fontToCqw(layout.fontSize);
            el.style.transform = `translate(-50%,-50%) scaleX(${layout.scaleX / 100})${layout.rotation ? ` rotate(${layout.rotation}deg)` : ''}`;
            el.style.textAlign = layout.align || '';
            el.style.letterSpacing = lsEm(layout.ls);
            if (layout.widthFit) fitPartWidth(); // "자동"이면 글자 크기·자간이 바뀌어도 계속 한 줄로 맞춤
            const lsV = box.querySelector('[data-val="ls"]'); if (lsV) lsV.textContent = ittLsText(layout.ls);
            box.querySelector('[data-act="w-auto"]')?.classList.toggle('on', !!(layout.widthAuto || layout.widthFit));
        }
        el.style.width = layout.widthAuto ? 'auto' : layout.width + '%';
        const fsEl = box.querySelector('[data-val="fs"]'); if (fsEl) fsEl.textContent = layout.fontSize + 'px';
        const sxEl = box.querySelector('[data-val="sx"]'); if (sxEl) sxEl.textContent = layout.scaleX + '%';
        const rotEl = box.querySelector('[data-val="rot"]'); if (rotEl) rotEl.textContent = (layout.rotation || 0) + '°';
        const wV = box.querySelector('[data-val="w"]'); if (wV) wV.textContent = layout.widthAuto ? '자동' : (Math.round(layout.width) + '%');
        syncFrame();
        positionToolbar();
        // 이것도 드래그처럼 renderPreview()를 안 거치고 화면을 직접 갱신하는 경로라 여기서 직접 기록한다.
        scheduleSnapshot();
    };
    // 아직 auto 폭인 상태에서 사용자가 처음 폭을 직접 건드릴 때, 현재 실측 폭을 기준값으로 잡아줌
    const ensureManualWidth = () => {
        if (!layout.widthAuto) return;
        const cRect = canvas.getBoundingClientRect();
        const eRect = el.getBoundingClientRect();
        layout.width = Math.max(15, Math.min(300, (eRect.width / cRect.width) * 100));
        layout.widthAuto = false;
    };
    box.querySelector('[data-act="fs-dec"]')?.addEventListener('click', () => { layout.fontSize = Math.max(6, Math.round((layout.fontSize - 0.5) * 10) / 10); apply(); });
    box.querySelector('[data-act="fs-inc"]')?.addEventListener('click', () => { layout.fontSize = Math.min(72, Math.round((layout.fontSize + 0.5) * 10) / 10); apply(); });
    box.querySelector('[data-act="sx-dec"]')?.addEventListener('click', () => { layout.scaleX = Math.max(50, Math.round((layout.scaleX - 0.5) * 10) / 10); apply(); });
    box.querySelector('[data-act="sx-inc"]')?.addEventListener('click', () => { layout.scaleX = Math.min(200, Math.round((layout.scaleX + 0.5) * 10) / 10); apply(); });
    box.querySelector('[data-act="rot-dec"]')?.addEventListener('click', () => { layout.rotation = Math.max(-180, Math.round(((layout.rotation || 0) - 1) * 10) / 10); apply(); });
    box.querySelector('[data-act="rot-inc"]')?.addEventListener('click', () => { layout.rotation = Math.min(180, Math.round(((layout.rotation || 0) + 1) * 10) / 10); apply(); });
    box.querySelectorAll('[data-align]').forEach(btn => {
        btn.classList.toggle('active', (layout.align || 'center') === btn.dataset.align);
        btn.addEventListener('click', () => {
            layout.align = btn.dataset.align;
            box.querySelectorAll('[data-align]').forEach(b => b.classList.toggle('active', b === btn));
            apply();
        });
    });
    box.querySelector('[data-act="w-dec"]')?.addEventListener('click', () => { ensureManualWidth(); layout.width = Math.max(15, Math.round(layout.width - 1)); apply(); });
    box.querySelector('[data-act="w-inc"]')?.addEventListener('click', () => { ensureManualWidth(); layout.width = Math.min(300, Math.round(layout.width + 1)); apply(); });
    // 줄 폭 "자동" = 글자가 최대한 한 줄에 들어가도록 내용 폭에 딱 맞춤 (칸 폭을 넘으면 그때만 줄바꿈)
    function fitPartWidth() {
        const cw = canvas.offsetWidth || 1;
        const prev = el.style.width;
        el.style.width = 'max-content';
        const natural = el.offsetWidth;
        el.style.width = prev;
        layout.width = Math.round(Math.max(15, Math.min(100, (natural + 4) / cw * 100 * 1.02)) * 10) / 10;
        layout.widthAuto = false;
    }
    box.querySelector('[data-act="w-auto"]')?.addEventListener('click', () => { layout.widthFit = true; apply(); });
    bindIttLs(box, () => layout.ls, v => { if (v) layout.ls = v; else delete layout.ls; }, apply);
    bindIttEdge(box, q => q === 'color' ? layout.glow : edgeOf(layout), (m, c) => { setEdge(layout, m, c); el.style.textShadow = textEdge(layout); scheduleSnapshot(); });
    bindIttColor(box, () => layout.color || '', c => { if (c) layout.color = c; else delete layout.color; el.style.color = c || ''; scheduleSnapshot(); });
    box.querySelector('select[data-act="font"]')?.addEventListener('change', e => {
        const id = e.target.value; if (id) { layout.font = id; loadFontCss(id); } else delete layout.font;
        el.style.fontFamily = partFontFamily(id); apply();
    });
    box.querySelector('[data-act="center-x"]')?.addEventListener('click', () => {
        layout.x = 50;
        el.style.left = '50%';
        syncFrame(); positionToolbar();
    });

    // 숫자를 더블클릭하면 직접 값을 입력할 수 있게 함
    bindEditableValue(box, 'fs', 6, 72, v => layout.fontSize = v, () => layout.fontSize, apply);
    bindEditableValue(box, 'sx', 50, 200, v => layout.scaleX = v, () => layout.scaleX, apply);
    bindEditableValue(box, 'rot', -180, 180, v => layout.rotation = v, () => layout.rotation || 0, apply);
    bindEditableValue(box, 'w', 15, 300, v => { layout.width = v; layout.widthAuto = false; }, () => layout.width, apply);
    box.querySelector('.tt-close').addEventListener('click', deselectPart);
    box.querySelector('[data-act="heart-del"]')?.addEventListener('click', () => { block.fields.hideHeart = true; deselectPart(); renderPreview(); if (selectedId === block.id) renderFieldEditor(); scheduleSnapshot(); });

    const NUDGE_STEP = 0.4; // % 단위 미세 이동
    box.querySelectorAll('[data-nudge]').forEach(btn => btn.addEventListener('click', () => {
        const dir = btn.dataset.nudge;
        if (dir === 'up') layout.y = Math.max(2, layout.y - NUDGE_STEP);
        if (dir === 'down') layout.y = Math.min(98, layout.y + NUDGE_STEP);
        if (dir === 'left') layout.x = Math.max(2, layout.x - NUDGE_STEP);
        if (dir === 'right') layout.x = Math.min(98, layout.x + NUDGE_STEP);
        el.style.left = layout.x + '%'; el.style.top = layout.y + '%';
        syncFrame(); positionToolbar();
        scheduleSnapshot(); // 예전엔 화살표 버튼으로 옮긴 건 되돌리기 기록에 안 남았음
    }));
    // PC 방향키 미세 이동(아래 initKeyboardNudge)이 쓰는 함수 - 화면 px 단위로 받아서 섹션 기준 %로 바꿔 옮김
    const nudgeByPx = (dxPx, dyPx) => {
        const cw = canvas.offsetWidth || 1, ch = canvas.offsetHeight || 1;
        layout.x = Math.round(Math.min(98, Math.max(2, layout.x + dxPx / cw * 100)) * 100) / 100;
        layout.y = Math.round(Math.min(98, Math.max(2, layout.y + dyPx / ch * 100)) * 100) / 100;
        el.style.left = layout.x + '%'; el.style.top = layout.y + '%';
        syncFrame(); positionToolbar();
    };

    // 선택 박스의 변/모서리 핸들: 변(w/e)은 줄바꿈 폭, 모서리는 글자 크기를 조절
    frame.querySelectorAll('[data-handle]').forEach(h => {
        let dragging = false, startX = 0, startY = 0, startWidth = 0, startFontSize = 0;
        h.addEventListener('pointerdown', e => {
            e.stopPropagation();
            dragging = true; h.setPointerCapture(e.pointerId);
            ensureManualWidth();
            delete layout.widthFit; // 손잡이로 폭을 직접 정하면 "자동" 해제
            startX = e.clientX; startY = e.clientY; startWidth = layout.width; startFontSize = layout.fontSize;
        });
        h.addEventListener('pointermove', e => {
            if (!dragging) return;
            const kind = h.dataset.handle;
            const dx = e.clientX - startX, dy = e.clientY - startY;
            const cRect = canvas.getBoundingClientRect();
            const dirX = kind.includes('e') ? 1 : -1; // e 계열 → 오른쪽으로 넓힘, w 계열 → 왼쪽으로 넓힘
            layout.width = Math.min(300, Math.max(15, startWidth + (dx / cRect.width * 100) * dirX * 2));
            if (!isImagePart && kind.length === 2) { // 모서리(nw/ne/sw/se)는 높이(글자 크기)도 같이 조절 (이미지 파츠는 제외)
                const dirY = kind.includes('s') ? 1 : -1; // s 계열 → 아래로 당기면 확대, n 계열 → 위로 당기면 확대
                layout.fontSize = Math.min(72, Math.max(6, Math.round((startFontSize + dy * dirY * 0.15) * 2) / 2));
            }
            apply();
        });
        h.addEventListener('pointerup', () => { dragging = false; });
    });

    if (!isImagePart) addSizeRotateHandles(frame, {
        canvas, el, minFs: 6, maxFs: 72,
        getFs: () => layout.fontSize, setFs: v => layout.fontSize = v,
        getRot: () => layout.rotation || 0, setRot: v => layout.rotation = v,
        apply,
    });

    window._ttOutsideHandler = e => { if (!box.contains(e.target) && !frame.contains(e.target) && e.target !== el) deselectPart(); };
    document.addEventListener('pointerdown', window._ttOutsideHandler, true);

    window._activeSelection = { frame, box, nudgeByPx, el };

    // 섹션 제목 레이어: 제목이 놓이는 칸의 높이도 여기서 조절 (칸이 커지면 제목을 더 아래·위로 옮길 수 있음)
    if (el.classList.contains('ib-title-layer')) {
        const isFree = !!el.dataset.hkey; // 자유 배치 칸(혼주·함께한 시간·손편지·게스트스냅): 칸 하나에 여러 문구
        const hKey = el.dataset.hkey || part + 'H', def = Number(el.dataset.th) || 44;
        const hMin = isFree ? 40 : 24, hMax = isFree ? 1200 : 320, hStep = isFree ? 10 : 8;
        const curH = () => Number(block.fields[hKey]) || def;
        const row = document.createElement('div');
        row.className = 'itt-row';
        row.innerHTML = `<small>${isFree ? '칸 높이' : '제목 칸'}</small><div class="itt-step"><button type="button" data-act="th-dec">−</button><span class="tt-val" data-val="th">${curH()}px</span><button type="button" data-act="th-inc">+</button></div>`;
        (box.querySelector('.tt-pos') || box.lastElementChild).before(row);
        const setH = v => {
            block.fields[hKey] = Math.max(hMin, Math.min(hMax, v));
            canvas.style.height = block.fields[hKey] + 'px';
            row.querySelector('[data-val="th"]').textContent = block.fields[hKey] + 'px';
            syncFrame(); positionToolbar(); scheduleSnapshot();
        };
        row.querySelector('[data-act="th-dec"]').addEventListener('click', () => setH(curH() - hStep));
        row.querySelector('[data-act="th-inc"]').addEventListener('click', () => setH(curH() + hStep));
        positionToolbar();
    }
}

function openLightbox(imgEl) {
    const allImgs = Array.from(imgEl.closest('.blk-gallery').querySelectorAll('img'));
    let idx = allImgs.indexOf(imgEl);
    const overlay = document.createElement('div');
    overlay.className = 'lightbox-overlay';
    overlay.innerHTML = `
        <button type="button" class="lb-close" aria-label="닫기">✕</button>
        ${allImgs.length > 1 ? `<button type="button" class="lb-prev" aria-label="이전">‹</button>
        <button type="button" class="lb-next" aria-label="다음">›</button>` : ''}
        <img class="lb-img" src="${allImgs[idx].src}" alt="">
    `;
    document.body.appendChild(overlay);
    const imgTag = overlay.querySelector('.lb-img');
    const close = () => { overlay.remove(); document.removeEventListener('keydown', onKey); };
    const onKey = e => { if (e.key === 'Escape') close(); if (e.key === 'ArrowLeft') step(-1); if (e.key === 'ArrowRight') step(1); };
    const step = dir => { idx = (idx + dir + allImgs.length) % allImgs.length; imgTag.src = allImgs[idx].src; };
    overlay.querySelector('.lb-close').addEventListener('click', close);
    overlay.addEventListener('click', e => { if (e.target === overlay) close(); });
    overlay.querySelector('.lb-prev')?.addEventListener('click', () => step(-1));
    overlay.querySelector('.lb-next')?.addEventListener('click', () => step(1));
    document.addEventListener('keydown', onKey);
}

document.getElementById('previewRoot').addEventListener('click', e => {
    if (e.target.matches('.blk-gallery .grid:not(.no-lightbox) img')) openLightbox(e.target);
    const fsBtn = e.target.closest('.video-fullscreen-btn');
    if (fsBtn) {
        if (document.fullscreenElement) {
            document.exitFullscreen?.(); // 이미 전체화면이면 꺼야 하는데, 항상 켜기만 시도하고 있었음
        } else {
            fsBtn.closest('.video-cover-wrap')?.requestFullscreen?.();
        }
    }
});
// 유튜브를 전체화면으로 키우면 그 영역만 화면을 차지해서, 바깥의 되돌리기/액션바 등은
// 화면엔 계속 겹쳐 보이면서 클릭만 안 먹히는 애매한 상태가 됨 - 전체화면 중엔 아예 숨긴다.
document.addEventListener('fullscreenchange', () => {
    const inFullscreen = !!document.fullscreenElement;
    document.querySelectorAll('.action-bar, .history-toggles, .topbar-icons, .controls-fab, .sections-fab').forEach(el => {
        el.style.display = inFullscreen ? 'none' : '';
    });
});
document.querySelector('.preview-pane').addEventListener('dblclick', e => {
    // 다중 선택 상태에서 요소가 아닌 다른(빈) 곳을 더블클릭하면 선택 전체 해제
    if (multiSelectMode && selectedParts.size > 0 && !e.target.closest('[data-drag-el]')) {
        clearMultiSelect();
    }
});
// 좁은화면(320px)을 실제 폭 축소 대신 시각적 scale() 축소로 구현한다.
// 레이아웃 계산 자체는 항상 표준(실기기) 폭 그대로 유지해서, 줄바꿈이 폭에 따라 달라지는 문제를 원천 차단한다.
// 화면폭/테두리 버튼을 누르면 미리보기 박스에 짧은 "펄스" 애니메이션을 줘서, 크기가 갑자기
// 순간이동하는 게 아니라 커지거나 작아지는 느낌이 들게 한다.
function pulseFrame() {
    const frame = document.getElementById('phoneFrame');
    if (!frame) return;
    frame.classList.remove('width-pulse');
    void frame.offsetWidth; // 리플로우를 강제해서 같은 애니메이션을 연속으로 눌러도 다시 재생되게 함
    frame.classList.add('width-pulse');
}
let narrowScaleRunning = false;
