        const isHalfZoom = frame.dataset.zoom === 'half';
        // 1.5배는 폰 주변 여백을 그대로 두고(표준처럼 가운데 떠 있게), 최대는 여백 없이 꽉 채운다
        if (pane) pane.style.padding = isHalfZoom ? '' : '0';
        const contentStandardWidth = 390 - bezelPad; // 표준 상태에서 실제로 쓰이는 콘텐츠 폭 그대로
        if (!contentStandardWidth) return;
