// ===== 되돌리기 탭: 왼쪽 아래 큼직한 ↶(되돌리기) ↷(다시하기) ✕(접기) - 손잡이 없이 탭 아무 곳이나 끌면 옮겨짐 =====
//  옮긴 자리·접은 상태는 이 기기에 기억 (PC·휴대폰 따로). 접으면 작은 ↶ 동그라미만 남고 누르면 다시 펼침
(function initUndoTab() {
    const SVG = d => `<svg viewBox="0 0 24 24" aria-hidden="true">${d}</svg>`;
    const tab = document.createElement('div');
    tab.className = 'undo-tab'; tab.id = 'undoTab';
    tab.innerHTML = `<button type="button" id="udUndo" title="되돌리기 (Ctrl+Z)" aria-label="되돌리기" disabled>${SVG('<path d="M9 14L4 9l5-5"/><path d="M4 9h10.5a5.5 5.5 0 0 1 0 11H11"/>')}</button>`
        + `<button type="button" id="udRedo" title="다시하기 (Ctrl+Y)" aria-label="다시하기" disabled>${SVG('<path d="M15 14l5-5-5-5"/><path d="M20 9H9.5a5.5 5.5 0 0 0 0 11H13"/>')}</button>`
        + `<button type="button" class="ud-x" title="작게 접기" aria-label="작게 접기">${SVG('<path d="M6 6l12 12M18 6L6 18"/>')}</button>`
        + `<button type="button" class="ud-open" title="되돌리기 버튼 펼치기" aria-label="되돌리기 버튼 펼치기">${SVG('<path d="M9 14L4 9l5-5"/><path d="M4 9h10.5a5.5 5.5 0 0 1 0 11H11"/>')}</button>`;
    document.body.appendChild(tab);
    const mob = () => window.innerWidth <= 860;
    const KEY = () => 'ldUndoTab_' + (mob() ? 'm' : 'pc');
    const load = () => { try { return JSON.parse(localStorage.getItem(KEY()) || 'null'); } catch (e) { return null; } };
    const save = st => { try { localStorage.setItem(KEY(), JSON.stringify(st)); } catch (e) {} };
    let st = load() || {};
    const place = () => {
        tab.classList.toggle('min', !!st.min);
        const w = tab.offsetWidth, h = tab.offsetHeight, vw = window.innerWidth, vh = window.innerHeight;
        const bar = document.querySelector('.action-bar'), barH = bar && mob() && getComputedStyle(bar).position === 'fixed' ? bar.getBoundingClientRect().height : 0;
        // 처음 자리: PC 왼쪽 아래 / 휴대폰은 아래 버튼줄·화면 크기 막대보다 위
        const wr = [...document.querySelectorAll('.mm-dock, .width-fab-row')].find(x => mob() && x.offsetWidth), wrr = wr ? wr.getBoundingClientRect() : null;
        const ab = bar && bar.offsetHeight ? bar.getBoundingClientRect().top : vh;
        let x = st.x != null ? st.x : 18, y = st.y != null ? st.y : (wrr && wrr.height ? wrr.top - h - 10 : (mob() ? ab : vh) - h - 22);
        x = Math.max(6, Math.min(vw - w - 6, x)); y = Math.max(60, Math.min(vh - h - 6 - barH, y));
        tab.style.left = x + 'px'; tab.style.top = y + 'px';
    };
    // 끌기: 4px 넘게 움직이면 끌기(버튼 눌림은 취소), 아니면 그냥 버튼 누름
    let d = null, moved = false;
    tab.addEventListener('pointerdown', e => {
        if (e.button > 0) return;
        const r = tab.getBoundingClientRect();
        d = { id: e.pointerId, x0: e.clientX, y0: e.clientY, l: r.left, t: r.top };
        moved = false;
    });
    window.addEventListener('pointermove', e => {
        if (!d || e.pointerId !== d.id) return;
        const dx = e.clientX - d.x0, dy = e.clientY - d.y0;
        if (!moved && Math.hypot(dx, dy) < 5) return;
        if (!moved) { moved = true; tab.classList.add('drag'); try { tab.setPointerCapture(e.pointerId); } catch (er) {} }
        e.preventDefault();
        st.x = d.l + dx; st.y = d.t + dy; place();
    }, { passive: false });
    const up = e => { if (!d || (e && e.pointerId !== d.id)) return; if (moved) { tab.classList.remove('drag'); save(st); } d = null; };
    window.addEventListener('pointerup', up); window.addEventListener('pointercancel', up);
    tab.addEventListener('click', e => {
        if (moved) { e.preventDefault(); e.stopPropagation(); moved = false; return; } // 끌고 놓은 건 누름이 아님
        const b = e.target.closest('button'); if (!b || b.disabled) return;
        if (b.id === 'udUndo') undoHistory();
        else if (b.id === 'udRedo') redoHistory();
        else if (b.classList.contains('ud-x')) { st.min = true; save(st); place(); }
        else if (b.classList.contains('ud-open')) { st.min = false; save(st); place(); }
    }, true);
    window.addEventListener('resize', () => { const k = KEY(); if (k !== place._k) { place._k = k; st = load() || {}; } place(); });
    place._k = KEY();
    requestAnimationFrame(place); window.addEventListener('load', place); [600, 1500, 3000].forEach(t => setTimeout(place, t)); // 화면 크기 막대·아래 버튼줄이 늦게 자리 잡아도 다시 맞춤
    // 숨겨져 있다가(디자인 고르기·간편 만들기 등) 보이게 되면 그때 크기로 다시 자리 잡음 - 숨긴 채 재면 높이 0이라 화면 아래로 반쯤 잘렸음
    if (window.ResizeObserver) new ResizeObserver(() => { if (tab.offsetWidth) place(); }).observe(tab);
    updateHistoryButtons();
})();

