// ===== 3단계 플로우: 디자인 선택 → 정보 입력 → 에디터 =====
function showScreen(name) {
    document.documentElement.classList.remove('ld-boot'); // 불러오기가 끝나 보여줄 화면이 정해짐
    document.querySelectorAll('.app-screen').forEach(s => s.classList.remove('active'));
    document.getElementById('screen' + name.charAt(0).toUpperCase() + name.slice(1)).classList.add('active');
    if (name !== 'editor') document.documentElement.classList.remove('simple-mode', 'sp-pv', 'sp-pv-real'); // 간편 화면은 에디터 화면 안에서만
    else if (typeof syncSimpleBtn === 'function') { if (state.mode === 'simple') document.documentElement.classList.add('simple-mode'); syncSimpleBtn(); }
    if (name === 'editor' && typeof ldhMaybeIntro === 'function') { try { ldhPlaceBtn(); ldhMaybeIntro(); } catch (e) {} } // 왕초보 도움말: 처음 한 번 사용법 안내
}

// ===== 시작 흐름(온보딩) =====
// 디자인(프리셋) → 기본 정보(마법사) → 인트로 → 꾸미기(에디터). 저장된 디자인이 이미 있으면 이 흐름 없이 바로 에디터.
// 만드는 방식: 'simple' 간편 만들기 (디자인 → 기본 정보 4단계 → 인트로 → 꾸미기) / 'custom' 직접 만들기 (바탕 → 두 사람 → 에디터)
// (P3 간편 에디터가 생기기 전까지 간편 만들기는 지금의 단계형 흐름을 쓴다)
let startTrack = 'simple';
const ONB_STEPS_BY = { simple: ['디자인', '칸 채우기', '발행'], custom: ['바탕', '두 사람', '꾸미기'] };
let onboardingActive = false;
let SAVE_OK = false, DATE_SET = false, DATE_DEMO = null, TIME_SET = false; const NAME_SET = new Set(), NAME_DEMO = {}; // 처음 저장 관문 (saveGateOk - 디자인을 고르고 두 분 이름 + 예식 날짜를 정한 뒤에)
function renderOnbSteps() {
    const ONB_STEPS = ONB_STEPS_BY[startTrack] || ONB_STEPS_BY.simple;
    document.querySelectorAll('.onb-steps[data-onb-step]').forEach(el => {
        const cur = parseInt(el.dataset.onbStep, 10);
        el.innerHTML = ONB_STEPS.map((label, i) =>
            (i ? '<span class="onb-sep"></span>' : '') +
            `<span class="onb-step ${i < cur ? 'done' : ''} ${i === cur ? 'current' : ''}"><b>${i < cur ? '✓' : i + 1}</b>${label}</span>`
        ).join('');
    });
}
let presetFilter = 'all';
// 추천 디자인 (관리자 → 추천 디자인, featured_presets.php) - 못 불러오면 기본 넷
let FEATURED_IDS = ['modern', 'classic', 'p-cinema', 'p-photos'], fpAllOpen = false;
// 관리자가 에디터로 꾸며 저장한 디자인 샘플 (sample_api.php?a=list) - id → {label, desc, base, custom}
let SAMPLE_LIST = {}, SAMPLE_LIST_OK = false;
fetch('sample_api.php?a=list', { cache: 'no-store' }).then(r => r.ok ? r.json() : null).then(j => {
    SAMPLE_LIST_OK = true;
    if (!j || !Array.isArray(j.items)) return;
    SAMPLE_LIST = {}; j.items.forEach(it => { SAMPLE_LIST[it.id] = it; });
    if (document.getElementById('screenDesign').classList.contains('active')) renderDesignScreen();
}).catch(() => {}).finally(() => { SAMPLE_LIST_OK = true; });
// 고르기 화면에 나올 디자인 = 폴더 프리셋 + 관리자가 새로 만든 샘플 (바탕 디자인의 미리보기 모양을 빌려 씀)
function allDesigns() {
    const extra = Object.values(SAMPLE_LIST).filter(it => it.custom).map((it, i) => {
        const b = PRESETS.find(p => p.id === it.base) || PRESETS[0] || {};
        return Object.assign({}, b, { id: it.id, label: it.label || b.label, desc: it.desc || b.desc, no: 100 + i, tags: [], __base: b.id, thumb: b.thumb });
    });
    const all = PRESETS.concat(extra).filter(presetShown), wx = p => p && (p.ambient === 'weather' || p.id === 'p-weather' || p.__base === 'p-weather');
    return all.filter(p => !wx(p)).concat(all.filter(wx)); // 날씨 따라 바뀌는 청첩장은 늘 맨 끝 (디자인을 더 넣어도)
}
// 저장된 샘플 디자인을 지금 상태에 입힌다 (불러오기와 같은 정리: 빠진 섹션 채우기·예전 저장분 옮기기)
function applySampleDesign(d) {
    if (!d || !Array.isArray(d.blocks)) return;
    registerSavedPalette(d.skin, d.palette);
    if (skins[d.skin]) state.skin = d.skin;
    ['bgm', 'share', 'labels', 'extras'].forEach(k => { state[k] = Object.assign({}, EXTRA_DEFAULTS[k], d[k] || {}); });
    state.imgFocus = d.imgFocus && typeof d.imgFocus === 'object' && !Array.isArray(d.imgFocus) ? d.imgFocus : {};
    state.imgZoom = d.imgZoom && typeof d.imgZoom === 'object' && !Array.isArray(d.imgZoom) ? d.imgZoom : {};
    state.customFont = d.customFont || null;
    state.customBg = d.customBg || null;
    state.paper = d.paper || null;
    state.sectionLook = d.sectionLook || '';
    state.lookStyle = d.lookStyle === 'old' ? 'old' : d.lookStyle === 'modern' ? 'modern' : (presetLookDefault(PRESETS.find(x => x.id === state.presetId)) === 'old' && lookOldAvail() ? 'old' : 'modern'); // 관리자가 꾸민 샘플에서 고른 꾸밈 스타일 (없으면 디자인 기본)
    state.backdrop = typeof d.backdrop === 'string' ? d.backdrop : null; // 페이지 배경 꾸밈 (없으면 꾸밈·디자인으로 짐작)
    state.customAccent = d.customAccent || null;
    state.themePal = d.themePal || curPalOf(); // 샘플은 샘플 색이 원래 색
    state.desktopSideBg = d.desktopSideBg || null;
    state.desktopShadow = !!d.desktopShadow;
    state.effects = Object.assign({ ambient: 'none', pinchZoom: true }, d.effects || {});
    state.intro = Object.assign({}, state.intro, d.intro || {});
    if (state.intro.font) loadFontCss(state.intro.font);
    state.blocks = JSON.parse(JSON.stringify(d.blocks));
    state.blocks = state.blocks.filter(b => b.id === 'heroVideo' || b.id === 'hero').concat(state.blocks.filter(b => b.id !== 'heroVideo' && b.id !== 'hero')); // 첫 화면은 항상 맨 위
    const have = new Set(state.blocks.map(b => b.id));
    DEFAULT_BLOCKS_TEMPLATE.forEach(db => { if (!have.has(db.id)) state.blocks.push(JSON.parse(JSON.stringify(db))); });
    state.stickers = Array.isArray(d.stickers) ? JSON.parse(JSON.stringify(d.stickers)) : [];
    state.customTexts = Array.isArray(d.customTexts) ? JSON.parse(JSON.stringify(d.customTexts)) : [];
    state.info = d.info && typeof d.info === 'object' ? Object.assign({}, d.info) : null;
    if (state.customFont) loadFontCss(state.customFont);
}
// 메인 레이아웃: 관리자가 저장한 것 받아오기 (간편 만들기 메인 화면 단계에 기본 레이아웃 뒤로 붙음) + 관리자면 저장 칸
let HL_ADMIN = false;
function hlRefreshEasy() { try { if (document.documentElement.classList.contains('simple-mode')) spRender(); } catch (e) {} }
fetch('hero_layouts.php?a=list', { cache: 'no-store' }).then(r => r.ok ? r.json() : null).then(j => { if (j && Array.isArray(j.items)) { HERO_LAYOUTS_ADMIN = j.items; hlRefreshEasy(); } }).catch(() => {});
