        if ((!DPK_TH && !THUMB_MAKE || !DPK_SECDEF) && Date.now() - (DPK.t0 || 0) < 3000) { DPK.busy = true; setTimeout(next, 150); return; } // 찍어 둔 그림 목록·메인 사진 예시를 받은 뒤에 (그림이 있으면 안 그려도 돼서)
