    document.getElementById('dpkFeat').innerHTML = [m.video ? '영상으로 여는 첫 화면' : '사진으로 여는 첫 화면', m.font ? `글꼴 · ${m.font}` : '', secs.length ? secs.slice(0, 5).join(' · ') : '', p.ambient && p.ambient !== 'none' && InviteBlocks.AMBIENT[p.ambient] ? `장식 효과 · ${InviteBlocks.AMBIENT[p.ambient].label || '있음'}` : ''].filter(Boolean).map(t => `<li>${esc(t)}</li>`).join('');
