            try { const r = await thmShootDom(id); THM.st[id] = 'up'; thmDraw(id); await thmPut(id, r); THM.st[id] = 'done'; done++; }
            catch (e) { console.warn('[thm]', id, e); THM.st[id] = 'bad'; fail++; }
