// PC 섹션 창 넓이: 창과 미리보기 사이 손잡이를 끌어서 (320~760px, 이 브라우저에 기억). 두 번 누르면 원래대로
(function paneResize() {
    const rz = document.getElementById('paneResizer'), pane = document.querySelector('#screenEditor .editor-pane');
    if (!rz || !pane) return;
    const set = w => { if (w) { pane.style.setProperty('--pane-w', w + 'px'); pane.classList.add('pw-set'); } else { pane.classList.remove('pw-set'); pane.style.removeProperty('--pane-w'); } };
    try { const w = parseInt(localStorage.getItem('ldPaneW') || '', 10); if (w) set(Math.max(320, Math.min(760, w))); } catch (e) {}
    rz.addEventListener('pointerdown', e => {
        if (e.button > 0) return;
        e.preventDefault();
        try { rz.setPointerCapture(e.pointerId); } catch (x) {}
        const x0 = e.clientX, w0 = pane.getBoundingClientRect().width, paneRight = pane.getBoundingClientRect().left > rz.getBoundingClientRect().left; // 창이 손잡이 오른쪽에 있으면 왼쪽으로 끌수록 넓어짐
        const maxW = Math.min(760, window.innerWidth - 420);
        let w = w0;
        rz.classList.add('drag'); document.body.classList.add('pane-resizing');
        const mv = ev => { w = Math.round(Math.max(320, Math.min(maxW, w0 + (paneRight ? x0 - ev.clientX : ev.clientX - x0)))); set(w); };
        const up = () => {
            rz.removeEventListener('pointermove', mv); rz.removeEventListener('pointerup', up); rz.removeEventListener('pointercancel', up);
            rz.classList.remove('drag'); document.body.classList.remove('pane-resizing');
            try { localStorage.setItem('ldPaneW', String(w)); } catch (x) {}
            window.dispatchEvent(new Event('resize')); // 미리보기 폭 맞춤 다시
        };
        rz.addEventListener('pointermove', mv); rz.addEventListener('pointerup', up); rz.addEventListener('pointercancel', up);
    });
    rz.addEventListener('dblclick', () => { set(0); try { localStorage.removeItem('ldPaneW'); } catch (x) {} window.dispatchEvent(new Event('resize')); });
})();
