        setTimeout(() => { const el = [...document.querySelectorAll('#simplePane .spb-li[data-li]')].find(x => x.dataset.li === tid); if (el) el.scrollIntoView({ block: 'start', behavior: 'smooth' }); if (st) try { spScrollPreview(st.s || []); } catch (e) {} }, 120);
        return;
