            const item = isCt ? (state.intro.customTexts || []).find(c => c.id === id) : (state.intro.stickers || []).find(x => x.id === id);
            const el = document.querySelector(isCt ? `#introOverlayStatic [data-ict-id="${id}"]` : `#introOverlayStatic [data-sticker-id="${id}"]`);
            if (!item || !el) return;
