                const canvas = el && el.closest('.drag-canvas');
                const L = block && partLayout(block, part, el, true);
                if (!L || !canvas) return;
                L.x = Math.round(Math.min(98, Math.max(2, L.x + dx / (canvas.offsetWidth || 1) * 100)) * 100) / 100;
                L.y = Math.round(Math.min(98, Math.max(2, L.y + dy / (canvas.offsetHeight || 1) * 100)) * 100) / 100;
