// ============ 섹션 편집창 도움말(팁) + 첫 방문 둘러보기 - 관리자 → 에디터 도움말(admin_tips.php) ============
// 편집창 안의 회색 안내 상자(.field-hint)가 "도움말"이다. 코드에서 지우지 않고, 관리자 설정(editor_tips.php)대로
//  - 전체 끄기(기본) / 켜기 · 팁마다 끄기 · 문구 바꾸기
//  - 기능(여러 개 같이 켤 수 있음): fold = ⓘ 눌러서 펼치기 / once = 처음 보는 팁만 펼쳐 보여주고 다음부터 접기
//                                  demo = 움직이는 시범 그림 / tour = 첫 방문 말풍선 둘러보기 (상단 ? 로 다시 보기)
// 팁마다 이름표(key)는 원래 문구로 만든 짧은 값 - 같은 문구는 여러 섹션에서 한 번만 고치면 다 바뀐다.
// 관리자 화면은 이 에디터를 ?tips=harvest 로 몰래 열어서 모든 섹션의 팁을 자동으로 모아 간다 (새 섹션·새 팁 자동 인식).
const TIP_CFG = { loaded: false, show: false, features: {}, tips: {}, guides: {}, guideTex: {}, tour: { ver: 1, steps: [] } };
const OPT_HARVEST = urlParams.get('opts') === 'harvest'; // 관리자 기기별 켜고 끄기: 전문가 편집 칸 이름 모으기 (harvestOpts)
const TIP_HARVEST = urlParams.get('tips') === 'harvest' || OPT_HARVEST; // (화면 밖에서 몰래 여는 것은 같음 - 안내 창·코치 투어 안 띄움)
const TIP_PICK = urlParams.get('tippick') === '1'; // 관리자 → 커스텀 편집팁: 화면에서 가리킬 곳 고르기 (저장 안 함)
const ADMIN_PV = urlParams.get('apv') === '1'; // 관리자 → 섹션 설정 → 편집창 모양: 오른쪽 미리보기 (편집창만 보여줌, 저장 안 함)
const tipStore = {
    get(k, d) { try { const v = localStorage.getItem(k); return v == null ? d : JSON.parse(v); } catch (e) { return d; } },
    set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} }
};
function isTipEl(el) {
    return el.classList.contains('field-hint') && !el.id && !el.hasAttribute('data-sf-val') && !el.hasAttribute('data-xs-val')
        && el.textContent.trim().length > 6; // 숫자만 보여주는 칸(예: "200px")은 팁이 아님
}
function tipText(el) { // 원래 문구 → 관리자 화면에서 고칠 수 있는 글 (굵게는 **글자**, 줄바꿈은 그대로)
    const c = el.cloneNode(true);
    c.querySelectorAll('b, strong').forEach(b => b.replaceWith('**' + b.textContent + '**'));
    c.querySelectorAll('br').forEach(b => b.replaceWith('\n'));
    return c.textContent.split('\n').map(l => l.replace(/\s+/g, ' ').trim()).filter(Boolean).join('\n');
}
function tipKey(el) {
    const t = el.textContent.replace(/\s+/g, ' ').trim();
    let h = 5381;
    for (const ch of t) h = (Math.imul(h, 33) ^ ch.codePointAt(0)) >>> 0;
    return 't' + h.toString(36);
}
function tipFormat(text) {
    return esc(text).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').replace(/\n/g, '<br>');
}
// 움직이는 시범: 손가락 동작 그림(CSS) 또는 관리자가 올린 GIF·영상
// 움직이는 시범: 프리셋 그림(assets/tip-demos.js · 48가지) 또는 관리자가 올린 GIF·영상.
// 시범을 따로 안 정한 도움말은 문구를 보고 알맞은 프리셋을 자동으로 고른다 (관리자 화면과 같은 규칙)
function tipAutoDemo(t) { return window.TipDemos ? TipDemos.auto(t) : ''; }
function tipDemoHtml(c) {
    if (c.media) {
        const u = 'uploads/site/tips/' + encodeURIComponent(c.media);
        return /\.(mp4|webm)$/.test(c.media)
            ? `<div class="tip-demo media"><video src="${u}" autoplay muted loop playsinline preload="metadata"></video></div>`
            : `<div class="tip-demo media"><img src="${u}" alt="" loading="lazy"></div>`;
    }
    return window.TipDemos ? TipDemos.html(c.demo) : '';
}
const TIP_OPEN_NOW = new Set(); // 지금 보고 있는 섹션에서 펼쳐 둔 팁
let tipSectionNow = null;
function applyTips(root) {
    if (!root || TIP_HARVEST) return;
    const F = TIP_CFG.features || {};
    // "처음 한 번만": 그 섹션을 보고 있는 동안만 펼쳐 두고, 다른 섹션으로 갔다 오면 접힘
    if (selectedId !== tipSectionNow) { tipSectionNow = selectedId; TIP_OPEN_NOW.clear(); }
    let seen = null;
    root.querySelectorAll('.field-hint:not([data-tip])').forEach(el => {
        if (!isTipEl(el)) { el.dataset.tip = 'na'; return; }
        if (!TIP_CFG.loaded) return; // 설정을 받기 전까지는 숨겨 둠 (CSS)
        const key = tipKey(el), c = TIP_CFG.tips[key] || {};
        el.dataset.tip = key;
        if (!TIP_CFG.show || c.on === false) return; // 숨김
        if (Array.isArray(c.offIn) && c.offIn.includes(selectedId)) return; // 여러 섹션 공통 팁인데 이 섹션에서는 꺼 둠 (관리자 → 공통 탭의 섹션 칩)
        const demo = c.demo === 'none' ? '' : (c.demo || tipAutoDemo(c.text || el.textContent));
        if (c.text) el.innerHTML = tipFormat(c.text);
        if (F.demo) { const d = tipDemoHtml({ media: c.media, demo }); if (d) el.insertAdjacentHTML('afterbegin', d); }
        el.dataset.tipOn = '1';
        // 접기: fold = 항상 접어둠 / once = 처음 보는 팁은 펼쳐서, 한 번 본 팁은 접어서
        if (seen === null) seen = tipStore.get('ldTipSeen', {});
        // 처음 보는 팁은 펼쳐서 (그 섹션에서 옵션을 눌러 편집창이 다시 그려져도 갑자기 접히지 않게)
        const first = F.once && (!seen[key] || TIP_OPEN_NOW.has(key));
        if (F.once) { seen[key] = 1; if (first) TIP_OPEN_NOW.add(key); }
        if (!F.fold && !F.once) return; // 상자로 바로 보임
        el.classList.add('tip-fold');
        const q = document.createElement('button');
        q.type = 'button'; q.className = 'tip-q';
        const setOpen = o => { el.classList.toggle('open', o); q.classList.toggle('open', o); q.innerHTML = `<span>i</span>${o ? '도움말 접기' : '도움말'}`; };
        q.addEventListener('click', () => { const o = !el.classList.contains('open'); setOpen(o); if (o) TIP_OPEN_NOW.add(key); else TIP_OPEN_NOW.delete(key); });
        setOpen(first);
        el.before(q);
    });
    if (seen) tipStore.set('ldTipSeen', seen);
    ensureSectionGuide(root);
}

// ---- 섹션별 사용법: 편집창 위 "▶ ○○ 사용법" → 그 섹션 기능을 움직이는 카드로 차례로 (관리자가 섹션마다 정함) ----
let guideOpen = null, guideIdx = 0, guideTimer = null; // 편집창이 다시 그려져도 펼친 상태·보던 카드 유지
function sectionGuideList(id) {
    const g = TIP_CFG.guides && TIP_CFG.guides[id];
    const list = Array.isArray(g) ? g : (window.TipDemos && TipDemos.guide ? TipDemos.guide(id) : []);
    return list.filter(x => x && x.on !== false && window.TipDemos && TipDemos.has(x.d));
}
function ensureSectionGuide(root) {
    if (!root || !TIP_CFG.loaded || !TIP_CFG.show || !(TIP_CFG.features || {}).guide || !selectedId) return;
    if (root.querySelector('.sgd-guide')) return;
    root.classList.remove('fe-guide');
    const gs = uip('guideStyle');
    const box = buildGuideBox(selectedId, blockLabels[selectedId] || '', gs);
    if (!box) return;
    const head = root.querySelector('h3');
    if (gs === 'G4') root.appendChild(box); // 맨 아래 한 줄 링크
    else if (head) head.after(box); else root.prepend(box);
    // 제목 줄 안으로 옮기는 버튼 (G1 ? · G2 칩 · G3 움직이는 그림 · G5 말풍선)
    if (head && ['G1', 'G2', 'G3', 'G5'].includes(gs)) { const ob = box.querySelector('.sgd-open'); const rb = head.querySelector('.layout-reset-btn'); if (rb) rb.before(ob); else head.appendChild(ob); }
    if (gs === 'G7') { const w = document.createElement('div'); w.className = 'sgd-fabwrap'; w.appendChild(box.querySelector('.sgd-open')); box.appendChild(w); }
    if (gs === 'G6' && guideOpen === selectedId) { root.classList.add('fe-guide'); box.querySelector('[data-sgd-edit]')?.classList.remove('on'); box.querySelector('.sgd-open')?.classList.add('on'); }
}
// 😀 스티커 창 맨 위에도 "▶ 스티커 사용법" (스티커는 섹션이 아니라서 관리자 화면에서는 "스티커 (꾸미기)"로 따로 정함)
function ensureStickerGuide() {
    const pal = document.getElementById('stickerPalette');
    if (!pal || pal.querySelector('.sgd-guide') || !TIP_CFG.loaded || !TIP_CFG.show || !(TIP_CFG.features || {}).guide) return;
    const box = buildGuideBox('sticker', '스티커');
    if (box) pal.prepend(box);
}
// "▶ ○○ 사용법" 버튼 + 펼치면 움직이는 카드가 차례로 넘어가는 상자 (섹션 편집창·스티커 창 공통)
function buildGuideBox(id, label, gs) {
    const list = sectionGuideList(id);
    if (!list.length) return null;
    const box = document.createElement('div');
    gs = gs || 'old';
    box.className = 'sgd-guide ' + gs.toLowerCase();
    const coachSeen = tipStore.get('ldGuideCoach', {});
    const BTN = {
        old: `<button type="button" class="sgd-open"><span>▶</span>${esc(label)} 사용법 <em>${list.length}</em></button>`,
        G1: `<button type="button" class="sgd-open g1" title="이 섹션 사용법" aria-label="이 섹션 사용법">?</button>`,
        G2: `<button type="button" class="sgd-open g2"><span>▶</span>사용법</button>`,
        G3: `<button type="button" class="sgd-open g3"><span class="sgd-mv"></span>사용법</button>`,
        G4: `<button type="button" class="sgd-open g4">💡 이 섹션 쓰는 법 보기<i>›</i></button>`,
        G5: coachSeen[id] ? `<button type="button" class="sgd-open g5q" title="이 섹션 사용법">?</button>` : `<button type="button" class="sgd-open g5">처음이세요? 30초 사용법<u>✕</u></button>`,
        G6: `<div class="sgd-tabs"><button type="button" class="on" data-sgd-edit>✎ 편집</button><button type="button" class="sgd-open g6">▶ 사용법 ${list.length}</button></div>`,
        G7: `<button type="button" class="sgd-open g7" title="이 섹션 사용법" aria-label="이 섹션 사용법">?</button>`,
        G8: `<button type="button" class="sgd-open g8"><b>TIP</b><span class="sgd-tk"></span><i>1/${list.length} ›</i></button>`,
    };
    box.innerHTML = (BTN[gs] || BTN.old) + `<div class="sgd-panel" hidden></div>`;
    const panel = box.querySelector('.sgd-panel'), openBtn = box.querySelector('.sgd-open');
    if (gs === 'G8') { // 한 줄 팁: 몇 초마다 다음 사용법 문장으로 바뀜, 누르면 그 카드부터 그림으로
        let ti = 0; const tk = openBtn.querySelector('.sgd-tk'), num = openBtn.querySelector('i');
        const txt = it => String(it.t || TipDemos.label(it.d) || '').replace(/\*\*/g, '');
        const step = () => { if (!openBtn.isConnected) { clearInterval(timer); return; } if (!panel.hidden) return; ti = (ti + 1) % list.length; tk.textContent = txt(list[ti]); tk.style.animation = 'none'; void tk.offsetWidth; tk.style.animation = ''; num.textContent = `${ti + 1}/${list.length} ›`; };
        tk.textContent = txt(list[0]);
        const timer = setInterval(step, 3200);
        openBtn.addEventListener('click', () => { guideIdx = ti; }, true);
    }
    if (gs === 'G5' && !coachSeen[id]) { // 처음만 말풍선: 누르거나 ✕를 누르면 다음부터 ?로
        openBtn.addEventListener('click', e => {
            coachSeen[id] = 1; tipStore.set('ldGuideCoach', coachSeen);
            const closeOnly = e.target.closest('u');
            openBtn.className = 'sgd-open g5q'; openBtn.textContent = '?'; openBtn.title = '이 섹션 사용법';
            if (closeOnly) { e.stopImmediatePropagation(); }
        }, true);
    }
    const stop = () => { clearTimeout(guideTimer); guideTimer = null; };
    // 저절로 다음 카드로 - 한 바퀴가 긴 시범(스티커 한눈에 등)은 끝까지 보고 넘어감, 마우스를 올리거나 손가락을 대면 잠깐 멈춤
    const tick = () => {
        if (!panel.isConnected || panel.hidden) { stop(); return; }
        if (panel.matches(':hover')) { guideTimer = setTimeout(tick, 800); return; }
        show(guideIdx + 1);
    };
    const schedule = () => { stop(); if (!panel.hidden) guideTimer = setTimeout(tick, Math.max(3800, (TipDemos.dur ? TipDemos.dur(list[guideIdx].d) : 0) + 400)); };
    const show = i => {
        guideIdx = (i + list.length) % list.length;
        const it = list[guideIdx];
        const tex = (TIP_CFG.guideTex || {})[id]; // 관리자가 고른 카드 바탕 무늬 (assets/tip-demos.css .tdx-*)
        panel.innerHTML = `<div class="sgd-stage${tex ? ' tdx-' + esc(tex) : ''}">${TipDemos.html(it.d)}</div>
            <p class="sgd-text">${tipFormat(it.t || TipDemos.label(it.d))}</p>
            <div class="sgd-nav"><button type="button" class="sgd-prev" aria-label="이전">‹</button>
                <span class="sgd-dots">${list.map((_, k) => `<i class="${k === guideIdx ? 'on' : ''}" data-k="${k}"></i>`).join('')}</span>
                <button type="button" class="sgd-next" aria-label="다음">›</button><button type="button" class="sgd-close">접기</button></div>`;
        schedule();
    };
    const open = (on, keepIdx) => {
        panel.hidden = !on; openBtn.classList.toggle('on', on);
        stop();
        if (!on) { if (guideOpen === id) guideOpen = null; return; }
        guideOpen = id;
        show(keepIdx ? guideIdx : 0);
    };
    openBtn.addEventListener('click', e => { e.stopPropagation(); const on = panel.hidden; open(on, gs === 'G8'); if (gs === 'G6') { document.getElementById('fieldEditor').classList.toggle('fe-guide', on); box.querySelector('[data-sgd-edit]').classList.toggle('on', !on); openBtn.classList.toggle('on', on); } if (on && gs === 'G7') panel.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); });
    box.querySelector('[data-sgd-edit]')?.addEventListener('click', e => { e.stopPropagation(); open(false); document.getElementById('fieldEditor').classList.remove('fe-guide'); e.currentTarget.classList.add('on'); openBtn.classList.remove('on'); });
    panel.addEventListener('click', e => {
        e.stopPropagation();
        if (e.target.closest('.sgd-prev')) show(guideIdx - 1);
        else if (e.target.closest('.sgd-next')) show(guideIdx + 1);
        else if (e.target.closest('.sgd-close')) { open(false); if (gs === 'G6') { document.getElementById('fieldEditor').classList.remove('fe-guide'); box.querySelector('[data-sgd-edit]')?.classList.add('on'); openBtn.classList.remove('on'); } }
        else { const d = e.target.closest('[data-k]'); if (d) show(+d.dataset.k); }
    });
    if (guideOpen === id) open(true, true);
    else if ((TIP_CFG.features || {}).once) { // "처음 한 번만"이 켜져 있으면 그 섹션(스티커 창)을 처음 열 때 저절로 펼침
        const seenG = tipStore.get('ldGuideSeen', {});
        if (!seenG[id]) { seenG[id] = 1; tipStore.set('ldGuideSeen', seenG); open(true); }
    }
    return box;
}

// ---- 첫 방문 둘러보기 (말풍선) ----
// 단계마다 짚을 곳 (여러 개면 그 버튼들을 한꺼번에 감쌈). 안 보이는 건 빼고, 하나도 안 보이면 가운데 말풍선만
const $id = id => document.getElementById(id);
const TOUR_TARGETS = {
    sections: () => window.innerWidth <= 860 ? $id('sectionsFabBtn') : $id('sectionsSheet'),
    expand: () => [...document.querySelectorAll('#blockList .row-expand-btn')].find(tourVisible),
    preview: () => $id('phoneFrame'),
    history: () => [$id('undoTab')],
    view: () => ['pWidthNormal', 'pWidthNarrow', 'pWidthFill', 'pZoomToggle', 'mWidthNormal', 'mWidthNarrow'].map($id),
    bezel: () => [$id('pBezelToggle'), $id('mBezelToggle')],
    save: () => document.querySelector('.action-bar')
};
function tourTargetRect(id) {
    const t = (TOUR_TARGETS[id] || (() => null))();
    const els = (Array.isArray(t) ? t : [t]).filter(tourVisible);
    if (!els.length) return null;
    const rs = els.map(e => e.getBoundingClientRect());
    return { left: Math.min(...rs.map(r => r.left)), top: Math.min(...rs.map(r => r.top)), right: Math.max(...rs.map(r => r.right)), bottom: Math.max(...rs.map(r => r.bottom)), el: els[0] };
}
let tourEl = null, tourSteps = [], tourIdx = 0;
function tourVisible(el) {
    if (!el || !el.getClientRects().length) return false; // display:none (fixed 요소는 offsetParent가 없어서 이걸로 확인)
    for (let p = el; p && p !== document.body; p = p.parentElement) { // 숨겨진 팝업(투명) 안에 있는 버튼은 제외
        const cs = getComputedStyle(p);
        if (cs.visibility === 'hidden' || cs.opacity === '0') return false;
    }
    const r = el.getBoundingClientRect();
    return r.width > 0 && r.height > 0 && r.bottom > 0 && r.top < window.innerHeight;
}
function startTour(force) {
    if (!TIP_CFG.show || !(TIP_CFG.features || {}).tour) return false;
    tourSteps = (TIP_CFG.tour.steps || []).filter(s => s.on);
    if (!tourSteps.length) return false;
    if (!force && tipStore.get('ldTourVer', 0) >= TIP_CFG.tour.ver) return false;
    tipStore.set('ldTourVer', TIP_CFG.tour.ver);
    closeAllPopups();
    if (!tourEl) {
        tourEl = document.createElement('div');
        tourEl.className = 'ld-tour';
        tourEl.innerHTML = `<div class="lt-hole"></div><div class="lt-card" role="dialog" aria-modal="true" aria-labelledby="ltTitle">
            <div class="lt-top"><span class="lt-step"></span><div class="lt-dots"></div></div>
            <h4 id="ltTitle"></h4><p></p>
            <div class="lt-btns"><button type="button" class="lt-skip">건너뛰기</button><button type="button" class="lt-prev">이전</button><button type="button" class="lt-next">다음</button></div></div>`;
        document.body.appendChild(tourEl);
        tourEl.querySelector('.lt-skip').addEventListener('click', endTour);
        tourEl.querySelector('.lt-prev').addEventListener('click', () => showTourStep(tourIdx - 1));
        tourEl.querySelector('.lt-next').addEventListener('click', () => tourIdx >= tourSteps.length - 1 ? endTour() : showTourStep(tourIdx + 1));
        window.addEventListener('resize', () => { if (tourEl.classList.contains('on')) placeTour(); });
        document.addEventListener('keydown', e => { if (tourEl.classList.contains('on') && e.key === 'Escape') endTour(); });
    }
    tourEl.classList.add('on');
    showTourStep(0);
    return true;
}
function endTour() {
    if (tourEl) tourEl.classList.remove('on');
    if (typeof maybeShowNotice === 'function') setTimeout(() => { if (tourForcedNotice) { tourForcedNotice = false; showNotice(true); } else maybeShowNotice(); }, 350);
}
let tourForcedNotice = false; // ? 버튼으로 둘러보기를 다시 볼 때는 끝나고 안내 팝업도 다시
function showTourStep(i) {
    tourIdx = Math.max(0, Math.min(tourSteps.length - 1, i));
    const s = tourSteps[tourIdx];
    const card = tourEl.querySelector('.lt-card');
    card.querySelector('.lt-step').textContent = `${tourIdx + 1} / ${tourSteps.length}`;
    card.querySelector('.lt-dots').innerHTML = tourSteps.map((_, k) => `<i class="${k === tourIdx ? 'on' : ''}"></i>`).join('');
    card.querySelector('h4').textContent = s.title;
    card.querySelector('p').innerHTML = tipFormat(s.text);
    card.querySelector('.lt-prev').hidden = tourIdx === 0;
    card.querySelector('.lt-next').textContent = tourIdx >= tourSteps.length - 1 ? '시작하기' : '다음';
    card.classList.remove('pop'); void card.offsetWidth; card.classList.add('pop');
    placeTour();
    card.querySelector('.lt-next').focus({ preventScroll: true });
}
function placeTour() {
    const s = tourSteps[tourIdx], hole = tourEl.querySelector('.lt-hole'), card = tourEl.querySelector('.lt-card');
    const r = tourTargetRect(s.id);
    const W = window.innerWidth, H = window.innerHeight, cw = Math.min(330, W - 24);
    card.style.width = cw + 'px';
    if (!r) { // 대상이 안 보이면(휴대폰에서 ⤢ 등) 가운데에 말풍선만
        Object.assign(hole.style, { left: W / 2 + 'px', top: H / 2 + 'px', width: '0px', height: '0px' });
        card.dataset.arrow = '';
        Object.assign(card.style, { left: (W - cw) / 2 + 'px', top: Math.max(16, (H - card.offsetHeight) / 2) + 'px' });
        return;
    }
    const pad = 8;
    const hr = { l: Math.max(4, r.left - pad), t: Math.max(4, r.top - pad), r: Math.min(W - 4, r.right + pad), b: Math.min(H - 4, r.bottom + pad) };
    Object.assign(hole.style, { left: hr.l + 'px', top: hr.t + 'px', width: (hr.r - hr.l) + 'px', height: (hr.b - hr.t) + 'px' });
    const ch = card.offsetHeight;
    let top, arrow;
    if (hr.b + 14 + ch < H - 8) { top = hr.b + 14; arrow = 'up'; }            // 아래
    else if (hr.t - 14 - ch > 8) { top = hr.t - 14 - ch; arrow = 'down'; }     // 위
    else { top = Math.max(8, Math.min(H - ch - 8, hr.t + 20)); arrow = ''; }   // 대상이 너무 크면 안쪽에
    let left = (hr.l + hr.r) / 2 - cw / 2;
    if (!arrow && hr.r + 14 + cw < W - 8) left = hr.r + 14;                    // PC: 큰 대상은 오른쪽 옆
    else if (!arrow && hr.l - 14 - cw > 8) left = hr.l - 14 - cw;
    left = Math.max(12, Math.min(W - cw - 12, left));
    card.dataset.arrow = arrow;
    card.style.setProperty('--ax', Math.max(18, Math.min(cw - 18, (hr.l + hr.r) / 2 - left)) + 'px');
    Object.assign(card.style, { left: left + 'px', top: top + 'px' });
}
// 편집 화면에 들어와 다른 창이 다 닫히면 한 번 시작
function maybeStartTour() {
    const ok = document.getElementById('screenEditor')?.classList.contains('active')
        && !document.querySelector('.start-guide.open, .ld-dlg.show, .field-drawer.popup-open, .sections-sheet.popup-open');
    if (ok && startTour(false)) return;
    if (tipStore.get('ldTourVer', 0) < TIP_CFG.tour.ver) setTimeout(maybeStartTour, 1200);
}

// ---- 첫 방문 안내 팝업 (관리자 → 에디터 도움말 → 첫 방문 안내) ----
// 기기마다 하나: 모바일 = 스크롤은 화면 양 끝에서 / PC = 빈 곳을 끌어서 여러 개 고르기. 브라우저마다 한 번 (ver가 오르면 다시)
// 도움말 전체(show)와 상관없이 기본으로 켜짐 - editor_tips.php를 못 불러와도 아래 기본 문구로 뜸
const NOTICE_DEF = [
    { id: 'mscroll', dev: 'm', on: true, title: '스크롤은 화면 양 끝에서', text: "미리보기 가운데는 글자·사진을 **고르는 곳**이라, 손가락이 닿으면 스크롤 대신 선택될 수 있어요.\n위아래로 내릴 때는 화면 **왼쪽·오른쪽 끝**을 밀어 주세요." },
    { id: 'pcmulti', dev: 'pc', on: true, title: '끌어서 여러 개 고르기', text: "미리보기의 **빈 곳을 마우스로 끌면** 사각형 안의 글자가 한꺼번에 골라져요.\n고른 것 중 하나를 끌면 **같이 옮겨지고**, **Shift+클릭**으로 하나씩 넣고 빼요. **Ctrl+A**는 보이는 글자 전부, **Esc**나 빈 곳 클릭으로 풀려요." },
];
TIP_CFG.notices = { ver: 1, items: NOTICE_DEF };
