function tipAgain(anchor) { if (ctTours().length) { ctChooser(anchor || document.getElementById('qtHelp')); return; } if (!startTour(true)) showNotice(true); else tourForcedNotice = !!noticeFor(); }

// 관리자 → 섹션 순서 → 편집창 모양의 "편집창 바탕" (색 + 무늬) - 섹션 편집창과 문구·스티커 팝업에 같이 씀
