            TIP_CFG.features = j.features && typeof j.features === 'object' ? j.features : {};
            TIP_CFG.tips = j.tips && typeof j.tips === 'object' ? j.tips : {};
            TIP_CFG.guides = j.guides && typeof j.guides === 'object' && !Array.isArray(j.guides) ? j.guides : {};
