        if (!ADMIN_PV && !TIP_PICK) setTimeout(maybeStartCTour, 4200); // 커스텀 편집팁 (처음 들어온 고객에게 한 번 - 위 둘이 끝난 뒤)
        syncTipBtn(); window.addEventListener('resize', syncTipBtn);
