    const hw = 34, hx = hr.r + hw + 4 < W ? Math.min(hr.r - 8, (hr.l + hr.r) / 2 + Math.min(60, (hr.r - hr.l) / 2) - 6) : hr.l - 4, hy = Math.min(H - 48, hr.b - 8);
