    if (okId(el.id) && uniq('#' + el.id)) return '#' + el.id;
    const ATTRS = ['data-sp-go', 'data-act', 'data-tog', 'data-sheet', 'data-ambient-val', 'data-amb-dir', 'data-sp-u', 'data-paper', 'data-xs-sb', 'data-view', 'data-mm-tog', 'data-tab', 'data-toggle', 'data-id', 'data-block-id', 'data-part', 'data-design', 'data-track', 'data-acct-chip', 'data-nb-st', 'data-shade', 'data-skin', 'aria-label', 'name', 'title'];
    const attrOf = n => ATTRS.find(a => { const v = n.getAttribute(a); return v != null && v !== '' && v.length < 60; });
    const a0 = attrOf(el);
    if (a0) { const s = `${el.tagName.toLowerCase()}[${a0}="${q(el.getAttribute(a0))}"]`; if (uniq(s)) return s; }
    const parts = [];
