        nextPicker: ['heroVideo', f => Object.assign(f, { youtubeId: f.youtubeId || spDemoYt(), heightMode: 'full', videoTextOver: true, nextBtn: true, nextStyle: f.nextStyle || 'glass' }), () => [...fe.querySelectorAll('.nbp, .pz-tl')].filter(x => x.matches('.nbp') || /스크롤/.test(x.textContent))],
        photoField: [['ending', 'notice', 'letter', 'profile', 'interview'].find(id => state.blocks.some(b => b.id === id)) || 'greeting', f => f, '.phf'],
        guideStyle: ['greeting', f => f, '.sgd-guide, [class*="sgd-"], .guide-chip'],
        feAnim: ['hero', heroSet, ''],
        jumpFix: ['hero', heroSet, '.ovt-tile, .ovt-ui'],
