    t.insertAdjacentHTML('afterbegin', `<span class="tg-ic">${tgIconSvg(full)}</span>`);
    // 글자는 칸 크기에 맞게 두 줄까지 (괄호 속 설명은 빼고, 전체 글은 길게 누르면/마우스를 올리면 보임)
